	},
	[20001] = {
		id = 20001,
		fmt = 'Chào mừng đến với Chiến tranh Tổ chức, mỗi tuần là một mùa, mỗi mùa có rất nhiều phần thưởng, mau gọi đồng đội đến chiến đấu cùng nhau!'
	},
	[20002] = {
		id = 20002,
		fmt = '1. Chiến tranh tổ chức chia 2 giai đoạn: Vòng loại và Chung kết; Vòng loại 4 ngày (Thứ Ba đến Thứ Sáu), Chung kết 1 ngày (Thứ Bảy)'
	},
	[20003] = {
		id = 20003,
