		fmt = '3. Thời gian bắt đầu thi đấu chính thức mỗi ngày: #C0xF76B45#21:00'
	},
	[20005] = {
		id = 20005,
		fmt = '4. Điều kiện đăng ký: Người chơi cấp 40 trở lên và tổ chức đang ở cấp 4 trở lên mới có thể đăng ký; phải đăng ký mới được tham gia thi đấu trong ngày đó'
	},
	[20006] = {
		id = 20006,
		fmt = '5. Người chơi VIP cấp 3 trở lên sẽ được hệ thống tự động đăng ký trước khi chiến đấu bắt đầu 30 phút'
	},
	[21001] = {
		id = 21001,
		fmt = '1. Trong vòng loại, từ Thứ Ba đến Thứ Năm sẽ giới hạn hệ thuộc tính Ninja tham chiến, có thể xem hạn chế cụ thể ở trang đăng ký hoặc trang xếp đội của ngày đó; Thứ Sáu không giới hạn hệ thuộc tính Ninja'
	},
	[21002] = {
		id = 21002,
		fmt = '2. Với các lượt có giới hạn thuộc tính, nếu Ninja có một thuộc tính trùng khớp thì có thể tham gia chiến đấu trong ngày đó; cùng một Ninja chỉ dùng được 1 lần/ngày'
	},
