		fmt = '4. Sau khi đội thứ nhất bị hạ, đội thứ hai có thể chiến đấu ở lượt tiếp theo'
	},
	[21005] = {
		id = 21005,
		fmt = '5. Thể thức thi đấu là chế độ hỗn chiến, bạn sẽ gặp người chơi từ các tổ chức khác (khi số người còn lại quá ít, bạn có thể phải đấu với thành viên trong chính tổ chức để phân định hạng cá nhân)'
	},
	[21006] = {
		id = 21006,
		fmt = '6. Người thắng có thể chiến đấu ở lượt tiếp theo và tiếp tục đối đầu với các đối thủ còn lại'
	},
	[21007] = {
		id = 21007,
		fmt = '7. HP và chakra sẽ được giữ lại sau mỗi trận chiến'
	},
	[21008] = {
		id = 21008,
		fmt = '8. Chiến tranh tổ chức có hệ thống điểm, luật điểm cá nhân: hạ 1 đối thủ được 2 điểm, thua được 1 điểm'
	},
	[21009] = {
		id = 21009,
		fmt = '9. Người thắng cuối cùng có thể tăng điểm tổ chức và Sao Chiến Đấu cho tổ chức; Sao Chiến Đấu có thể dùng để điều chỉnh bonus thuộc tính trong Phán Quyết Số Mệnh'
