	[22003] = {
		id = 22003,
		fmt = '3. Chung kết là chiến giữa tổ chức với tổ chức, chế độ loại trực tiếp và tiến cấp cho đến khi quyết định vô địch'
	},
	[22004] = {
		id = 22004,
		fmt = '4. Chế độ chiến đấu chung kết là luân phiên giữa các tổ chức, người chơi có thể dùng 3 đội Ninja thi đấu, mỗi đội có thể đưa tối đa 4 người vào chiến'
	},
	[22005] = {
		id = 22005,
		fmt = '5. Khi hai tổ chức giao chiến, sẽ thi đấu theo thứ tự ra trận; đội thắng sẽ đánh tiếp trận sau, đội thua sẽ bị loại khỏi thứ tự ra trận, cho đến khi toàn bộ đội của một bên bị tiêu diệt thì bên kia thắng'
	},
	[22006] = {
		id = 22006,
		fmt = '6. Tổ chức thắng có thể tiếp tục đấu với các tổ chức thắng khác cho đến khi quyết định vô địch'
	},
	[22007] = {
		id = 22007,
		fmt = '7. Trạng thái Ninja sẽ được giữ nguyên trong suốt chuỗi chung kết; dù thắng, HP của Ninja sẽ không hồi khi đấu với tổ chức thắng tiếp theo, và Ninja đã chết sẽ không hồi sinh'
	},
	[22008] = {
		id = 22008,
		fmt = '8. Sau khi trận chiến tranh tổ chức cuối cùng kết thúc, sẽ cộng rất nhiều điểm thưởng cho tổ chức theo thứ hạng'
	},
	[22101] = {
		id = 22101,
		fmt = '1. Trong vòng loại, tổ chức thắng cuối cùng mỗi ngày có thể nhận 1 Sao Chiến Đấu'
	},
	[22102] = {
		id = 22102,
		fmt = '2. Trước khi bắt đầu Phán Quyết Số Mệnh, quản lý tổ chức (Thủ lĩnh/Trưởng lão) có Sao Chiến Đấu có thể dùng Sao Chiến Đấu để thiết lập bonus thuộc tính và trị số năng lực cho chung kết'
	},
	[22103] = {
		id = 22103,
		fmt = '3. Thiết lập thành công sẽ tiêu hao 1 Sao Chiến Đấu và không thể thay đổi sau khi thiết lập'
	},
	[22104] = {
		id = 22104,
		fmt = '4. Sau khi thiết lập xong, thay đổi năng lực đó sẽ áp dụng lên toàn bộ Ninja tham gia chung kết'
	},
	[22201] = {
		id = 22201,
		fmt = '1. Trong suốt thời gian chiến tranh tổ chức, ở mỗi lượt chiến đấu, toàn bộ Ninja vào đội chiến đấu lần đầu sẽ nhận bonus thuộc tính như Taijutsu, Ninjutsu, Phòng thủ, Kháng, Tốc độ,... '
	},
	[22202] = {
		id = 22202,
		fmt = '2. Khi chiến đấu tiếp diễn, bonus thuộc tính sẽ giảm dần, Ninja sẽ mệt mỏi và sức chiến đấu sẽ yếu đi dần'
	},
	[22203] = {
		id = 22203,
		fmt = '3. Sau đó, mỗi lần tham gia chiến đấu, các thuộc tính như Taijutsu, Ninjutsu, Phòng thủ, Kháng, Tốc độ, Lượng trị liệu,... của Ninja trong đội sẽ tiếp tục giảm'
	},
	[22301] = {
		id = 22301,
		fmt = '1. Trong giai đoạn đăng ký chung kết (Thứ Bảy 9:30-20:50) có thể đặt cược dự đoán kết quả chung kết'
	},
	[22302] = {
		id = 22302,
		fmt = '2. Đặt cược vô địch, tỉ lệ càng cao, lợi nhuận càng lớn, tối đa không quá 1000000 xu đồng'
	},
	[22303] = {
		id = 22303,
		fmt = '3. Sau khi giải kết thúc, thưởng sẽ được phát đồng loạt qua thư; đoán đúng vô địch sẽ nhận tiền theo tỉ lệ đặt cược, đoán đội về nhì sẽ được hoàn lại một nửa số tiền đã cược'
	},
	[23001] = {
		id = 23001,
		fmt = '1. Sau khi giải kết thúc, tất cả phần thưởng sẽ được gửi qua thư'
	},
	[23002] = {
		id = 23002,
		fmt = '2. Thưởng mỗi ngày gồm thưởng đăng ký, thưởng thắng cá nhân, thưởng xếp hạng tổ chức; trong đó thưởng xếp hạng tổ chức sẽ do người tham gia thi đấu của tổ chức đó nhận'
	},
	[23003] = {
		id = 23003,
		fmt = '3. Đăng ký vòng loại và chung kết đều có thể nhận 1 bộ thưởng tham gia'
	},
	[23004] = {
		id = 23004,
		fmt = '4. Thưởng thắng cá nhân là Rương thắng Chiến tranh Tổ chức, thắng 1 lần được 1 rương; mỗi ngày nhận tối đa 6 rương; chỉ hạ đối thủ trong vòng loại mới nhận được, trong Phán Quyết Số Mệnh không có thưởng thắng cá nhân'
	},
	[23005] = {
		id = 23005,
		fmt = '5. Thưởng xếp hạng tổ chức xem chi tiết trong hiển thị thưởng bên dưới'
	},
	[24001] = {
		id = 24001,
		fmt = '#C0xFFF5D6#1. Mỗi tuần sẽ có 2 lượt thi đấu, mỗi lượt kéo dài 2 ngày, thời gian bắt đầu là Thứ Hai và Thứ Sáu hằng tuần'
	},
	[24002] = {
		id = 24002,
		fmt = '#C0xFFF5D6#2. Mỗi vòng thi đấu sẽ ghép cặp các server có sức mạnh và số lượng người chơi gần tương đương nhau'
	},
	[24003] = {
		id = 24003,
		fmt = '#C0xFFF5D6#3. Thời gian đăng ký: Ngày đầu của mỗi vòng thi đấu 05:00-18:50'
	},
	[24004] = {
		id = 24004,
		fmt = '#C0xFFF5D6#4. Thời gian bắt đầu: 19:00'
	},
	[24005] = {
		id = 24005,
		fmt = '#C0xFFF5D6#5. Khi đăng ký phải chọn 12 Ninja, có thể tự do thay đổi trước khi bắt đầu thi đấu chính thức mỗi ngày'
	},
	[24006] = {
		id = 24006,
		fmt = '#C0xFFF5D6#6. Mỗi vòng thi đấu gồm tổng cộng 3 giai đoạn: Vòng loại, Vòng 8 Khu, và Chung kết'
	},
	[24007] = {
		id = 24007,
		fmt = '#C0xFFF5D6#7. Mỗi trận Vòng loại kéo dài 4 phút; mỗi trận Vòng 8 Khu và Chung kết kéo dài 5 phút; không thể chỉnh đội hình trong 1 phút trước khi bắt đầu trận'
	},
	[24008] = {
		id = 24008,
		fmt = '#C0xFFF5D6#8. VIP3 trở lên có thể tự động đăng ký'
	},
	[25001] = {
		id = 25001,
		fmt = '#C0xFFF5D6#1. Thắng 1 trận nhận 1 Rương Vàng, thua 1 trận nhận 1 Rương Bạc'
	},
	[25002] = {
		id = 25002,
		fmt = '#C0xFFF5D6#2. Sau khi mỗi vòng thi đấu kết thúc sẽ phát thưởng xếp hạng theo thứ hạng của bạn'
	},
	[25003] = {
		id = 25003,
