	},
	[25004] = {
		id = 25004,
		fmt = '#C0xFFF5D6#4. Thưởng xếp hạng sẽ phát qua thư sau khi mỗi vòng thi đấu kết thúc'
	},
	[26001] = {
		id = 26001,
		fmt = '#C0xFFF5D6#1. Vòng loại là thể thức loại theo điểm'
	},
	[26002] = {
		id = 26002,
		fmt = '#C0xFFF5D6#2. Vòng loại chia 3 lượt: Ngày 1 đấu 2 lượt, ngày 2 đấu 1 lượt; mỗi lượt 4 trận, tổng 12 trận; mỗi trận 4 phút'
	},
	[26003] = {
		id = 26003,
		fmt = '#C0xFFF5D6#3. Mỗi trận đấu, người chơi sẽ nhận điểm tương ứng'
	},
	[26004] = {
		id = 26004,
		fmt = '#C0xFFF5D6#4. Điểm và số trận thắng/thua được kế thừa giữa các lượt vòng loại; tích lũy 5 lần thua sẽ bị loại ngay'
	},
	[26005] = {
		id = 26005,
		fmt = '#C0xFFF5D6#5. Ninja không thể dùng lại trong cùng một lượt thi đấu, nhưng có thể dùng lại giữa các lượt khác nhau'
	},
	[27001] = {
		id = 27001,
		fmt = '#C0xFFF5D6#1. Sau khi vòng loại kết thúc, chọn top 64 theo xếp hạng để vào Vòng 8 Khu; Vòng 8 Khu chia thành 8 bảng'
	},
	[27002] = {
