		fmt = '#C0xFFF5D6#1. Người thắng cuối cùng của Vòng 8 Khu có thể vào Chung kết'
	},
	[28002] = {
		id = 28002,
		fmt = '#C0xFFF5D6#2. Chung kết là thể thức loại trực tiếp, gồm Vòng 4, Bán kết và Chung kết, tổng 3 trận'
	},
	[28003] = {
		id = 28003,
		fmt = '#C0xFFF5D6#3. Mỗi trận 5 phút'
	},
	[28004] = {
		id = 28004,
		fmt = '#C0xFFF5D6#4. Ninja không thể dùng lại'
	},
	[29001] = {
		id = 29001,
		fmt = '#C0xFFF5D6#1. Vòng loại, Vòng 8 Khu và Chung kết đều là luân phiên 3v3'
	},
	[29002] = {
		id = 29002,
		fmt = '#C0xFFF5D6#2. Ninja ra trận có tổng Tốc độ cao hơn sẽ ra tay trước; nếu Tốc độ bằng nhau thì tổng Lực chiến cao hơn sẽ ra tay trước'
	},
	[29003] = {
		id = 29003,
		fmt = '#C0xFFF5D6#3. Hai Ninja đấu với nhau, tối đa 10 hiệp'
	},
	[29004] = {
		id = 29004,
		fmt = '#C0xFFF5D6#4. Kết thúc 10 hiệp nếu cả hai vẫn chưa bị hạ, bên có %HP còn lại cao hơn sẽ thắng'
	},
	[29005] = {
		id = 29005,
		fmt = '#C0xFFF5D6#5. Bên còn Ninja sống sót cuối cùng sẽ là bên thắng'
	},
	[30001] = {
		id = 30001,
		fmt = '#C0xFFF5D6#1. Ngày đầu, người chơi có thể đặt cược số trận thắng của bản thân ở vòng loại là số chẵn hay lẻ'
	},
	[30002] = {
		id = 30002,
		fmt = '#C0xFFF5D6#2. Ngày hai có thể đặt cược vô địch trong top 64 người chơi có tổng lực chiến cao nhất của khu đó'
	},
	[30003] = {
		id = 30003,
		fmt = '#C0xFFF5D6#3. Đặt cược vô địch, tỉ lệ càng cao lợi nhuận càng lớn, mỗi vòng tối đa nhận 1500000 xu đồng'
	},
	[30004] = {
		id = 30004,
		fmt = '#C0xFFF5D6#4. Nếu mục tiêu đặt cược vào top 4 sẽ hoàn 1.5 lần số tiền; nếu không vào top 4 sẽ hoàn một nửa số tiền'
	},
	[30005] = {
		id = 30005,
		fmt = '#C0xFFF5D6#5. Dưới đây là thưởng xếp hạng:'
	},
	[31001] = {
		id = 31001,
		fmt = '#C0x08ED1F#Ninja phát hiện một lục địa giàu khoáng sản, nghe đồn tại cửa hàng của lục địa đó có thể dùng khoáng để đổi rất nhiều phần thưởng, vì vậy các Nhà huấn luyện thú đổ xô tham gia tranh đoạt khoáng'
	},
	[31002] = {
		id = 31002,
		fmt = '#C0xFFF5D6#1. Thời gian diễn ra Chiến tranh Khoáng liên server: #C0x08ED1F#Thứ Bảy 10:00 - Thứ Hai tuần sau 22:00'
	},
	[31003] = {
		id = 31003,
		fmt = '#C0xFFF5D6#2. Khung giờ có thể tranh đoạt mỗi ngày: #C0x08ED1F#10:00 - 22:00'
	},
	[31004] = {
		id = 31004,
		fmt = '#C0xFFF5D6#3. Mỗi ngày có #C0x08ED1F#3 lượt tranh đoạt miễn phí'
	},
	[31005] = {
		id = 31005,
		fmt = '#C0xFFF5D6#4. Mỗi vòng thi đấu sẽ ghép nhiều server có sức mạnh và số lượng người chơi gần tương đương; các server thi đấu với nhau, khi kết thúc sẽ xếp hạng theo tổng điểm của người chơi trong phạm vi thứ hạng chỉ định của mỗi server; server có tổng điểm cao hơn sẽ xếp hạng cao hơn'
	},
	[31006] = {
		id = 31006,
		fmt = '#C0xFFF5D6#5. Chiến tranh Khoáng liên server có thưởng cá nhân cuối cùng; thưởng cá nhân cuối cùng được quyết định bởi hạng server và tổng điểm: Thưởng cá nhân cuối cùng = thưởng cơ bản theo hạng server + thưởng theo tỉ lệ điểm; vì vậy hạng server càng cao, điểm càng nhiều, thưởng cá nhân cuối cùng càng lời'
	},
	[31007] = {
		id = 31007,
		fmt = '#C0xFFF5D6#6. Mỗi điểm khoáng tương ứng một thứ hạng, hạng càng cao điểm càng cao; Nhà huấn luyện thú có thể khiêu chiến người chơi hạng cao hơn qua khu khoáng lân cận để tăng hạng, hoặc trực tiếp khiêu chiến top 10 của điểm khoáng qua khu khoáng cấp cao'
	},
	[32001] = {
		id = 32001,
		fmt = '#C0xFFF5D6#1. Tài nguyên khoáng có thể dùng để cổ vũ Thú Khoáng và đổi vật phẩm trong Cửa hàng Chiến tranh Khoáng'
	},
	[32002] = {
		id = 32002,
		fmt = '#C0xFFF5D6#2. Cổ vũ Thú Khoáng có thể nhận buff tăng thêm cho toàn server hoặc cá nhân'
	},
	[32003] = {
		id = 32003,
		fmt = '#C0xFFF5D6#3. Điểm khoáng có thể sản xuất khoáng, tính mỗi 10 phút; hạng càng cao tốc độ sản xuất càng nhanh'
	},
	[32004] = {
		id = 32004,
		fmt = '#C0xFFF5D6#4. Nhà huấn luyện thú có thể bắt đầu tranh đoạt điểm khoáng của người chơi khác'
	},
	[32005] = {
		id = 32005,
		fmt = '#C0xFFF5D6#5. Tranh đoạt người chơi cùng server, nếu đối phương có lực chiến thấp hơn bản thân quá nhiều thì sẽ không thể nhận được khoáng'
	},
	[32006] = {
		id = 32006,
		fmt = '#C0xFFF5D6#6. Điểm khoáng có giới hạn bị tranh đoạt, mỗi lần tranh đoạt không thể vượt quá giới hạn bị tranh đoạt'
	},
	[32007] = {
		id = 32007,
		fmt = '#C0xFFF5D6#7. Chiến tranh Khoáng liên server cạnh tranh rất khốc liệt, trong quá trình tranh đoạt khoáng của mục tiêu có thể thay đổi, tài nguyên cuối cùng cướp được có thể ít hơn số thấy trên màn tranh đoạt, ra tay trước sẽ có lợi'
	},
	[33001] = {
		id = 33001,
		fmt = '#C0xFFF5D6#1. Nhà huấn luyện thú có thể đưa 3 đội Ninja vào chiến đấu, mỗi đội tối đa 4 người'
	},
	[33002] = {
		id = 33002,
		fmt = '#C0xFFF5D6#2. Chiến đấu theo thể thức 3 ván 2 thắng'
	},
	[33003] = {
		id = 33003,
		fmt = '#C0xFFF5D6#3. Hai bên đấu tối đa 20 hiệp, nếu trong 20 hiệp vẫn chưa phân thắng bại thì tính phe phòng thủ thắng'
	},
	[34001] = {
		id = 34001,
		fmt = '#C0xFFF5D6#1. Trong báo cáo chiến tranh có thể bắt đầu báo thù người đã tranh đoạt mình; chỉ có thể báo thù khi bị tranh đoạt thành công, và nếu người bị tranh đoạt đang được bảo vệ khiến không bị cướp khoáng thì không thể báo thù'
	},
	[34002] = {
		id = 34002,
		fmt = '#C0xFFF5D6#2. Báo thù tương tự tranh đoạt, có thể cướp khoáng của đối phương nhưng không thay đổi thứ hạng'
	},
	[34003] = {
		id = 34003,
		fmt = '#C0xFFF5D6#3. Nhà huấn luyện thú có 5 lượt báo thù mỗi ngày, lượt này tính riêng với tranh đoạt'
	},
	[35001] = {
		id = 35001,
		fmt = '#C0xFFF5D6#1. Trong thời gian sự kiện, mỗi ngày lúc 22:00 sẽ phát thưởng xếp hạng cá nhân qua thư'
	},
	[35002] = {
		id = 35002,
		fmt = '#C0xFFF5D6#2. Hạng càng cao thưởng càng lời, thưởng là lượng lớn tài nguyên khoáng và xu đồng'
	},
	[36001] = {
		id = 36001,
		fmt = '#C0xFFF5D6#Ma thú muốn phá hủy và tái tạo thế giới ninja, thả ra rất nhiều bánh răng đen, khống chế rất nhiều Ninja, mỗi ngày còn thả một phần Ninja ra quấy phá; để giúp thế giới ninja, hãy hợp sức thanh tẩy Ninja bị bánh răng đen khống chế!'
	},
	[36002] = {
		id = 36002,
		fmt = '#C0xFFF5D6#1. Mỗi ngày lúc 12:00 sẽ làm mới quân đoàn Ninja Hắc mới'
	},
	[36003] = {
		id = 36003,
		fmt = '#C0xFFF5D6#2. Mỗi ngày lúc 12:00, Người triệu hồi khắp thế giới có thể lập đội hoặc tham gia đội của người khác để cùng chống lại Ninja bị bánh răng đen khống chế'
	},
	[36004] = {
		id = 36004,
		fmt = '#C0xFFF5D6#3. Thanh tẩy Ninja theo đội có thể nhận mảnh Ninja tương ứng'
	},
	[36005] = {
		id = 36005,
		fmt = '#C0xFFF5D6#4. Muốn thanh tẩy Ninja nào thì phải có Ninja đó trước'
	},
	[36006] = {
		id = 36006,
		fmt = '#C0xFFF5D6#5. Mỗi lần thắng có thể nhận 2 Rương Báu: rương thứ nhất mở miễn phí, rương thứ hai cần vàng; cả hai đều có cơ hội ra mảnh Ninja'
	},
	[36007] = {
		id = 36007,
		fmt = '#C0xFFF5D6#6. Trong mỗi nhiệm vụ thanh tẩy, người chơi hoàn thành càng nhiều trận chiến sẽ nhận thưởng đặc biệt càng nhiều; thưởng đặc biệt gửi qua thư, điều kiện nhận là bản thân phải hoàn thành toàn bộ trận chiến'
	},
	[36008] = {
		id = 36008,
		fmt = '#C0xFFF5D6#7. Khi 3 người, 4 người và 5 người trong đội hoàn thành chiến đấu sẽ nhận thưởng đặc biệt ở các mức khác nhau'
	},
	[36009] = {
		id = 36009,
		fmt = '#C0xFFF5D6#8. Sau khi chọn mục tiêu thanh tẩy, chỉ cần thắng 1 trận sẽ không thể rời đội hiện tại, phải chiến đấu đến hết!'
	},
	[36010] = {
		id = 36010,
		fmt = '#C0xFFF5D6#9. Mỗi ngày lúc 12:00 đội cũ sẽ tự giải tán, phải lập đội mới'
	},
	[36011] = {
		id = 36011,
		fmt = '#C0xFFF5D6#10. Người chơi có thể bấm vào ảnh đại diện của mình trong đội để đổi Ninja ra trận'
	},
	[37001] = {
		id = 37001,
		fmt = '1. Vòng loại, Vòng 8 Khu và Chung kết đều là luân phiên 3v3'
	},
	[37002] = {
		id = 37002,
		fmt = '2. Ninja ra trận có tổng Tốc độ cao hơn sẽ ra tay trước; nếu Tốc độ bằng nhau thì tổng Lực chiến cao hơn sẽ ra tay trước'
	},
	[37003] = {
		id = 37003,
		fmt = '3. Hai Ninja đấu với nhau, tối đa 10 hiệp'
	},
	[37004] = {
		id = 37004,
		fmt = '4. Kết thúc 10 hiệp nếu cả hai vẫn chưa bị hạ, bên có %HP còn lại cao hơn sẽ thắng'
	},
	[37005] = {
		id = 37005,
		fmt = '5. Bên còn Ninja sống sót cuối cùng sẽ là bên thắng'
	},
	[38001] = {
		id = 38001,
		fmt = '1. Ngày đầu, người chơi có thể đặt cược số trận thắng của bản thân ở vòng loại là số chẵn hay lẻ'
	},
	[38002] = {
		id = 38002,
		fmt = '2. Ngày hai có thể đặt cược vô địch trong top 20 người chơi có tổng lực chiến cao nhất của khu đó'
	},
	[38003] = {
		id = 38003,
		fmt = '3. Đặt cược vô địch, tỉ lệ càng cao lợi nhuận càng lớn, mỗi vòng tối đa nhận 1000000 xu đồng'
	},
	[38004] = {
		id = 38004,
		fmt = '4. Nếu mục tiêu đặt cược vào top 4 sẽ hoàn 1.5 lần số tiền; nếu không vào top 4 sẽ hoàn một nửa số tiền'
	},
	[39001] = {
		id = 39001,
		fmt = '1. Thời gian đăng ký: #C0xF76B45#10:00-19:50'
	},
	[39002] = {
		id = 39002,
		fmt = '2. Thời gian thi đấu: #C0xF76B45#20:00-20:55'
	},
	[39003] = {
		id = 39003,
		fmt = '3. Khi đăng ký có thể chọn tối đa 10 Ninja ra trận, sau khi đăng ký thành công có thể thay đổi đội hình'
	},
	[39004] = {
		id = 39004,
		fmt = '4. Thi đấu chia 2 phần: Vòng loại và Vòng 8 Khu; top 8 của Vòng loại sẽ vào Vòng 8 Khu'
	},
	[39005] = {
		id = 39005,
		fmt = '5. 1 phút trước khi bắt đầu thi đấu, người chơi không thể chỉnh đội hình ra trận'
	},
	[39006] = {
		id = 39006,
		fmt = '6. Người chơi VIP3 trở lên sẽ được hệ thống tự động đăng ký trước khi kết thúc đăng ký mỗi ngày 50 phút'
	},
	[39007] = {
		id = 39007,
		fmt = '7. Thời gian chiến đấu hai bên tối đa 10 hiệp, hết hiệp nếu vẫn chưa phân thắng bại: nếu cả hai bên đều có HP > 90% thì bên gây tổng sát thương cao hơn thắng; nếu có bên nào có %HP < 90% thì bên có %HP cuối cùng cao hơn thắng'
	},
	[39008] = {
		id = 39008,
		fmt = '8. Thi đấu có xếp hạng điểm, điểm được quyết định bởi sát thương Ninja gây ra, sát thương càng cao điểm càng cao'
	},
	[39009] = {
		id = 39009,
		fmt = '9. Mỗi ngày lúc 10:00 có thể bắt đầu đặt cược, tỉ lệ càng cao lợi nhuận càng lời, mỗi ngày tối đa nhận 100 vạn xu đồng'
	},
	[39010] = {
		id = 39010,
		fmt = '10. Nếu mục tiêu đặt cược vào Vòng 8 Khu nhưng không vô địch sẽ hoàn lại một phần tiền cược; nếu không vào Vòng 8 Khu sẽ không hoàn tiền'
	},
	[40001] = {
		id = 40001,
		fmt = '1. Vòng loại là thể thức loại trực tiếp, tổng cộng 10 trận, mỗi trận 4 phút; xếp hạng theo số trận thắng, nếu số trận thắng bằng nhau thì xếp theo điểm'
	},
	[40002] = {
		id = 40002,
		fmt = '2. Mỗi trận đưa 1 Ninja vào chiến đấu'
	},
	[40003] = {
		id = 40003,
		fmt = '3. Vòng loại tích lũy #C0xF76B45#3 lần thua sẽ bị loại ngay'
	},
	[40004] = {
		id = 40004,
		fmt = '4. Mỗi trận người chơi có thể nhận điểm, sau khi vòng loại kết thúc sẽ chọn top 8 theo số trận thắng và điểm để vào Vòng 8 Khu'
	},
	[40005] = {
		id = 40005,
		fmt = '5. Ninja không thể dùng lại'
	},
	[41001] = {
		id = 41001,
		fmt = '1. Giai đoạn Vòng 8 Khu cũng là thể thức loại trực tiếp, gồm Vòng 4, Bán kết, Chung kết và Tranh hạng 3, tổng 4 trận; mỗi trận 5 phút'
	},
	[41002] = {
		id = 41002,
		fmt = '2. Mỗi trận, người chơi phải đưa 3 Ninja, luân phiên ra theo thứ tự'
	},
	[41003] = {
		id = 41003,
		fmt = '3. Cả 3 Ninja bị hạ hết sẽ tính là thua'
	},
	[41004] = {
		id = 41004,
		fmt = '4. Ninja không thể dùng lại'
	},
	[42001] = {
		id = 42001,
		fmt = '1. Mỗi lần thi đấu, người chơi có thể nhận 1 Rương Báu'
	},
	[42002] = {
		id = 42002,
		fmt = '2. Thắng nhận Rương Vàng, thua nhận Rương Bạc'
	},
	[42003] = {
		id = 42003,
		fmt = '3. Cả hai loại rương đều có cơ hội mở ra phần thưởng hiếm'
	},
	[42004] = {
		id = 42004,
		fmt = '4. Theo thứ hạng thi đấu Ninja Đại của ngày đó có thể nhận thưởng xếp hạng'
	},
	[43001] = {
		id = 43001,
		fmt = '#C0xFFF5D6#1. Ban đầu mỗi ngày có thể chơi 5 lần, trong viện nghiên cứu nâng cấp công nghệ.'
	},
	[43002] = {
		id = 43002,
		fmt = '#C0xFFF5D6#2. Khi bắt đầu lượt chơi này có thể đổi số lần lắc miễn phí 5 lần, tương tự có thể tăng công nghệ liên quan trong Viện nghiên cứu để tăng số lần đổi lắc miễn phí'
	},
	[43003] = {
		id = 43003,
		fmt = '#C0xFFF5D6#3. Thú Thần Hỏa đã lắc ra sẽ không biến mất 4. Thú Thần Hỏa càng nhiều, phần thưởng càng lời, có thể nhận mảnh Thú Thần Hỏa và rất nhiều Xu Tổ Chức'
	},
	[43004] = {
		id = 43004,
		fmt = '#C0xFFF5D6#4. Thú Thần Hỏa càng nhiều, phần thưởng càng lời, có thể nhận mảnh Thú Thần Hỏa và rất nhiều Xu Tổ Chức'
	},
	[44001] = {
		id = 44001,
		fmt = '1. Thời gian mở Phó bản Tổ chức: Thứ Hai đến Thứ Bảy 9:30-23:30, Chủ Nhật nghỉ'
	},
	[44002] = {
		id = 44002,
		fmt = '2. Thứ Hai, Thứ Tư, Thứ Sáu lúc 5:00 hệ thống tự reset phó bản; chỉ reset phó bản ở độ khó cao nhất trong tiến độ hiện tại; Thứ Ba, Thứ Năm, Thứ Bảy lúc 23:30 sau khi phó bản tổ chức đóng sẽ tính toán và phát thưởng xếp hạng sát thương cùng lúc'
	},
	[44003] = {
		id = 44003,
		fmt = '3. Mỗi ngày có 3 lượt khiêu chiến, tất cả phó bản dùng chung số lượt này, reset mỗi ngày lúc 5:00; trong quá trình khiêu chiến có cơ hội nhận Rương Boss Tổ chức'
	},
	[44004] = {
		id = 44004,
		fmt = '4. Vượt qua phó bản hiện tại sẽ mở phó bản tiếp theo; phó bản đã vượt qua không thể chơi lại trước khi reset theo tháng'
	},
	[44005] = {
		id = 44005,
		fmt = '5. Sau khi hoàn thành mỗi phó bản tổ chức, sẽ phát thưởng xếp hạng sát thương đặc biệt theo mức đóng góp trong phó bản'
	},
	[44006] = {
		id = 44006,
		fmt = '6. Mỗi phó bản có thưởng vượt ải lần đầu, mỗi người chơi chỉ nhận được 1 lần'
	},
	[44007] = {
		id = 44007,
		fmt = '7. Tùy theo số lượng phó bản tổ chức đã vượt và thời gian ở trong tổ chức, người chơi trong tổ chức sẽ nhận bonus Tấn công/Phòng thủ/HP; bonus này chỉ có hiệu lực trong phó bản hiện tại'
	},
	[44008] = {
		id = 44008,
		fmt = '8. Đầu mỗi tháng reset toàn bộ phó bản; sau mỗi lần reset, mỗi khi vượt 1 phó bản thì toàn tổ chức có thể nhận thưởng tiêu diệt (không phải thưởng lần đầu)'
	},
	[44009] = {
		id = 44009,
		fmt = '9. Thưởng tiêu diệt (không phải thưởng lần đầu), mỗi người chơi ở mỗi phó bản trong mỗi lần reset chỉ nhận được 1 lần'
	},
	[44010] = {
		id = 44010,
		fmt = '10. Sau khi đổi tổ chức, trong ngày đó không thể khiêu chiến phó bản tổ chức, phải đợi đến 5:00 ngày hôm sau mới có thể làm'
	},
	[44011] = {
		id = 44011,
		fmt = '11. Người chơi tích điểm cho mỗi Boss tổ chức có thể nhận thưởng xu đồng và vàng đặc biệt; thưởng tiêu diệt của cùng một Boss trong một chu kỳ reset 1 tháng chỉ nhận được 1 lần'
	},
	[44012] = {
		id = 44012,
		fmt = '12. Tất cả thưởng tiêu diệt phải tự nhận trong rương thưởng; thưởng tham gia và thưởng tích điểm sẽ phát khi tính toán khiêu chiến; thưởng xếp hạng sát thương phát qua thư'
	},
	[45001] = {
		id = 45001,
		fmt = '1. Mỗi thành viên tổ chức có thể cầu nguyện 1 lần/ngày, công khai Ninja muốn nhận mảnh làm “Ước nguyện” trong tổ chức'
	},
	[45002] = {
		id = 45002,
		fmt = '2. Khi cầu nguyện chỉ có thể dùng Ninja mà bản thân hiện đang sở hữu làm mục tiêu cầu nguyện'
	},
	[45003] = {
		id = 45003,
		fmt = '3. Ninja chất lượng khác nhau thì số lượng tối đa nhận được mỗi lần cầu nguyện sẽ khác nhau; chất lượng càng cao thì số lượng có thể nhận càng ít'
	},
	[45004] = {
		id = 45004,
		fmt = '4. Có thể tặng mảnh mình có cho thành viên tổ chức khác để giúp họ hoàn thành ước nguyện; tối đa tặng cho cùng một thành viên 1 mảnh'
	},
	[45005] = {
		id = 45005,
		fmt = '5. Sau khi tặng mảnh Ninja sẽ gửi qua thư đến hộp thư của thành viên tổ chức nhận'
	},
	[45006] = {
		id = 45006,
		fmt = '6. Tặng mảnh Ninja chất lượng khác nhau sẽ nhận Đá Linh Hồn Ninja và Điểm Hảo Tâm với số lượng khác nhau'
	},
	[45007] = {
		id = 45007,
		fmt = '7. Mỗi ngày lúc 5:00 sẽ xóa toàn bộ danh sách cầu nguyện'
	},
	[46001] = {
		id = 46001,
		fmt = '#C0xFFF5D6#1. Mỗi lần thi đấu, người chơi có thể nhận 1 Rương Báu'
	},
	[46002] = {
		id = 46002,
		fmt = '#C0xFFF5D6#2. Thắng nhận Rương Vàng, thua nhận Rương Bạc'
	},
	[46003] = {
		id = 46003,
		fmt = '#C0xFFF5D6#3. Cả hai loại rương đều có cơ hội mở ra Nhẫn, Bát giác và các vật phẩm khác'
	},
	[46004] = {
		id = 46004,
		fmt = '#C0xFFF5D6#4. Theo thứ hạng chiến đấu Vua của ngày đó có thể nhận thưởng xếp hạng, bao gồm mảnh Thiên Sứ Thú và các vật phẩm hiếm khác'
	},
	[47001] = {
		id = 47001,
		fmt = '1. Khảm hợp kim vào ô Ma trận của Ninja, Ninja có thể nhận bonus chỉ số hợp kim; ô ma trận sẽ mở theo cấp đội'
	},
	[47002] = {
		id = 47002,
		fmt = '2. Đặt hợp kim đúng loại vào ô ma trận chỉ định có thể kích hoạt bonus thuộc tính Ma trận, sức mạnh Ninja sẽ được tăng thêm'
	},
	[47003] = {
		id = 47003,
		fmt = '3. Hiệu ứng ma trận có mạnh/yếu theo chất lượng; khi toàn bộ hợp kim kích hoạt hiệu ứng ma trận đạt một chất lượng nào đó thì hiệu ứng ma trận cũng có thể nâng lên chất lượng đó; tức là mạnh/yếu của hiệu ứng ma trận phụ thuộc vào hợp kim có chất lượng thấp nhất trong ma trận'
	},
	[47004] = {
		id = 47004,
		fmt = '4. Khi Ninja đã kích hoạt một hiệu ứng ma trận và ô ma trận hiện tại còn chỗ trống, có thể tự chọn đặt hợp kim yêu thích vào chỗ trống, sẽ không ảnh hưởng đến việc kích hoạt hiệu ứng ma trận'
	},
	[47005] = {
		id = 47005,
		fmt = '5. Hợp kim dư có thể chuyển thành Lõi Hợp Kim thông qua nung chảy hợp kim; Lõi Hợp Kim có thể dùng để tăng cấp các hợp kim khác'
	},
	[48001] = {
		id = 48001,
		fmt = 'Hoàn thành nhiệm vụ hằng ngày trong danh sách sẽ nhận điểm Nhiệt Huyết tích lũy tương ứng'
	},
	[48002] = {
		id = 48002,
		fmt = 'Khi điểm Nhiệt Huyết hằng ngày tích lũy đạt 20, 40, 60, 80, 100 có thể nhận thưởng trong rương thưởng tích lũy Nhiệt Huyết'
	},
	[48003] = {
		id = 48003,
		fmt = 'Một số nhiệm vụ Nhiệt Huyết như tích lũy online, tiêu hao thể lực... có thể hoàn thành theo từng bước, mỗi bước sẽ nhận điểm Nhiệt Huyết của bước đó'
	},
	[49001] = {
		id = 49001,
		fmt = '1. Trong rương giới hạn thời gian, mỗi lần mở 1 rương sẽ nhận 10 điểm; điểm cao thấp quyết định thứ hạng trên bảng xếp hạng; khi điểm bằng nhau, người đạt mốc điểm đó trước sẽ xếp trên'
	},
	[49002] = {
		id = 49002,
		fmt = '2. Trong sự kiện này, mỗi lần mở 10 rương trang bị chắc chắn nhận Hợp kim Thức tỉnh và Rương Mảnh Vạn năng (không ra mảnh thức tỉnh)'
	},
	[49003] = {
		id = 49003,
		fmt = '3. Thời gian kết thúc sự kiện là ngày cuối cùng lúc 21:30; sau khi sự kiện kết thúc sẽ không thể mở rương nữa; thưởng top 30 sẽ phát qua thư'
	},
	[49004] = {
		id = 49004,
		fmt = '4. Thưởng xếp hạng hạng 1 phải đạt 7000 điểm'
	},
