		id = 84005,
		fmt = '5. Sau khi phân giải Ấn có thể nhận vật liệu cường hóa Ấn, dùng để cường hóa Ấn khác'
	},
	[85001] = {
		id = 85001,
		fmt = '1. Trong thời gian sự kiện, người chơi có thể dùng Ninja khiêu chiến Boss Thế Giới'
	},
	[85002] = {
		id = 85002,
		fmt = '2. Mỗi lần khiêu chiến Boss Thế Giới sẽ ghi nhận lượng sát thương của người chơi, đạt mốc sát thương mục tiêu tương ứng có thể nhận ngay thưởng trong rương thưởng tương ứng sau khi lần khiêu chiến này kết thúc'
	},
	[85003] = {
		id = 85003,
		fmt = '3. Boss Thế Giới ghi nhận tổng sát thương tối đa của toàn server, sau khi đạt mục tiêu, người chơi tham gia sự kiện trong ngày đó có thể nhận thưởng rương; thưởng phát qua thư lúc 5:00 ngày hôm sau, đồng thời lúc này reset dữ liệu sát thương tích lũy'
	},
	[85004] = {
		id = 85004,
		fmt = '4. Boss Thế Giới có số lượt khiêu chiến miễn phí và có thể mua thêm; sau khi số lượt đạt giới hạn trong ngày đó sẽ không thể vào chiến đấu nữa; số lượt reset lúc 5:00 ngày hôm sau'
	},
	[85005] = {
		id = 85005,
		fmt = '5. Sát thương cao nhất cá nhân trong một lần khiêu chiến Boss Thế Giới trong ngày đó sẽ được ghi vào BXH cá nhân và BXH tổ chức; BXH và ghi nhận sát thương reset lúc 5:00 ngày hôm sau'
	},
	[85006] = {
		id = 85006,
		fmt = '6. Người chơi và tổ chức lên BXH sẽ nhận thưởng xếp hạng, xem mẫu thưởng vui lòng bấm nút thưởng xếp hạng; thưởng phát qua thư lúc 5:00 ngày hôm sau'
	},
	[85007] = {
		id = 85007,
		fmt = '7. Người chơi không tham gia tổ chức sẽ không vào BXH tổ chức; nếu tham gia tổ chức trước khi reset dữ liệu thì chỉ ghi nhận dữ liệu khiêu chiến Boss Thế Giới sau khi vào tổ chức mới'
	},
	[85008] = {
		id = 85008,
		fmt = '8. Người chơi đang có tổ chức, sau khi vào chiến Boss Thế Giới rồi rời tổ chức, trước khi reset dữ liệu mà gia nhập tổ chức lại sẽ không tạo dữ liệu sát thương của mình trong tổ chức mới'
	},
	[86001] = {
		id = 86001,
		fmt = '1. Đấu trường liên server cần chờ ghép cặp giữa các server, khi ghép cặp thành công sẽ hiển thị #C0xF76B45#Trạng thái ghép cặp thành công chờ mở thi đấu#C0xFFFFFF# trên màn hình'
	},
	[86002] = {
		id = 86002,
		fmt = '2. Quy trình mùa: #C0xF76B45#Mùa bắt đầu (2 tuần 14 ngày) — Mùa kết thúc hiển thị người chơi (liên tục 5 ngày) — Chuẩn bị mở thi đấu (thông báo trước 2 ngày)'
	},
	[86003] = {
		id = 86003,
		fmt = '3. Trong mùa có 2 lần tính xếp hạng: #C0xF76B45#Ngày 7 của mùa lúc 22:00 tính theo giai đoạn, và ngày 14 lúc 22:00 tính mùa khi kết thúc mùa'
	},
	[86004] = {
		id = 86004,
		fmt = '4. Trong mùa, mỗi ngày có số lượt khiêu chiến miễn phí và có thể dùng vàng mua thêm lượt khiêu chiến; số lượt reset mỗi ngày lúc 5:00'
	},
	[86005] = {
		id = 86005,
		fmt = '5. Người chơi có thể tự làm mới đối thủ có thể khiêu chiến; làm mới thủ công có số lượt miễn phí, dùng hết lượt miễn phí thì phải dùng xu đồng làm mới đối thủ; số lượt miễn phí làm mới thủ công reset mỗi ngày lúc 5:00'
	},
	[86006] = {
		id = 86006,
		fmt = '6. Cấp mùa phân biệt cấp lớn và cấp nhỏ; cấp lớn theo thứ tự #C0xF76B45#Đồng—Bạc—Vàng—Platinum—Vàng—Đại sư Vô Úy—Vương Giả Đỉnh Cao#C0xFFFFFF# từ thấp lên cao; cấp nhỏ theo số, số càng nhỏ xếp càng cao; Đại sư Vô Úy và Vương Giả Đỉnh Cao không có cấp nhỏ'
	},
	[86007] = {
		id = 86007,
		fmt = '7. Mỗi cấp nhỏ có xếp hạng nội bộ, thứ hạng có giới hạn; mỗi người chơi xếp tổng theo Cấp > Thứ hạng trong cấp (cấp không có cấp nhỏ thì xếp theo cấp lớn)'
	},
	[86008] = {
		id = 86008,
		fmt = '8. Trong dữ liệu chiến đấu có thể xem video chiến đấu giữa các người chơi cấp cao trong thời gian gần đây'
	},
	[87001] = {
		id = 87001,
		fmt = '1. Trước chiến đấu, người chơi có thể xếp 2 đội, có thể đưa vào chiến không ít hơn 2 và không nhiều hơn 12 Ninja'
	},
	[87002] = {
		id = 87002,
		fmt = '2. Chiến đấu dùng luân phiên 6V6, tối đa 3 hiệp; đội thắng hiệp 1 sẽ giữ trạng thái hiện tại để tiếp tục khiêu chiến đội tiếp theo của đối phương'
	},
	[87003] = {
		id = 87003,
		fmt = '3. Nếu cả 2 đội của một bên đều thua hết thì tính là thua; nếu hết hiệp vẫn chưa phân thắng bại thì bên còn nhiều máu hơn tính là thắng'
	},
	[87004] = {
		id = 87004,
		fmt = '4. Cách chiến đấu của đấu trường liên server là #C0xF76B45#khóa tự động chiến đấu#C0xFFFFFF#'
	},
	[87005] = {
		id = 87005,
		fmt = '5. Người chơi chủ động khiêu chiến đối thủ, nếu thắng sẽ hoán đổi thứ hạng với đối phương; nếu thua thứ hạng không đổi'
	},
	[87006] = {
		id = 87006,
		fmt = '6. Khi đối phương chủ động khiêu chiến người chơi, sẽ đưa đội hình phòng thủ của người chơi ra chiến; thay đổi thứ hạng và quan hệ kết thúc chiến đấu giống như điều trước'
	},
	[88001] = {
		id = 88001,
		fmt = '1. Sau khi khiêu chiến hằng ngày đạt số lượt nhiệm vụ, có thể tự nhận thưởng ở tab Thưởng thi đấu - Thưởng hằng ngày, mỗi ngày lúc 5:00 reset nhiệm vụ'
	},
	[88002] = {
		id = 88002,
		fmt = '2. Khi cập nhật kỷ lục cấp cao nhất, có thể tự nhận thưởng ở tab Thưởng thi đấu - Thưởng cấp; thưởng này sẽ reset sau khi mỗi mùa kết thúc'
	},
	[88003] = {
		id = 88003,
		fmt = '3. Hai lần tính xếp hạng trong quá trình mùa sẽ phát thưởng qua thư theo cấp; chi tiết thưởng có thể xem ở Thưởng thi đấu - Bảy ngày mùa, tab Mùa trước'
	},
	[89001] = {
		id = 89001,
		fmt = '1. Trao đổi độ yêu thích cần một số điều kiện giới hạn\n     Điều kiện①: Hình thái ban đầu của Ninja hai bên có cùng độ hiếm\n     Điều kiện②: Vật liệu tiêu hao khi bồi dưỡng độ yêu thích của hai bên tương ứng nhau'
	},
	[89002] = {
		id = 89002,
		fmt = '2. Khi trao đổi độ yêu thích, chỉ cần đã kích hoạt Bách khoa Ninja thỏa điều kiện là được; dù trong túi không có Ninja tương ứng cũng có thể trao đổi độ yêu thích'
	},
	[90001] = {
		id = 90001,
		fmt = '1. Loại Ấn up giới hạn của mỗi đợt sự kiện sẽ thay đổi'
	},
	[90002] = {
		id = 90002,
		fmt = '2. Mỗi ngày có 1 lượt mở giới hạn miễn phí, lúc 5:00 ngày hôm sau reset số lượt miễn phí'
	},
	[90003] = {
		id = 90003,
		fmt = '3. Số lượt mở mỗi ngày có một số giới hạn, không bao gồm lượt mở miễn phí'
	},
	[91001] = {
		id = 91001,
		fmt = '1. Số lần đổi Ấn của mỗi đợt sự kiện Ấn giới hạn có một số giới hạn, vượt quá số lần giới hạn trong đợt này sẽ không thể đổi tiếp'
	},
	[91002] = {
		id = 91002,
		fmt = '2. Đổi Ấn giới hạn chỉ áp dụng cho phẩm chất tím và tím trở lên, và Ấn cùng phẩm chất'
	},
	[91003] = {
		id = 91003,
		fmt = '3. Đổi Ấn cần ít nhất 2 hoặc 3 Ấn cùng phẩm chất #C0xF76B45##L10#Tiêu hao 2 Ấn cùng phẩm chất chỉ có thể đổi được 1 Ấn mới cùng phẩm chất, tiêu hao 3 Ấn cùng phẩm chất có thể đổi 2 Ấn mới cùng phẩm chất'
	},
	[91004] = {
		id = 91004,
		fmt = '4. Cách đổi Ấn có 3 kiểu:'
	},
	[91005] = {
		id = 91005,
		fmt = '①[Loại giới hạn] và [Số hiệu giới hạn] mặc định không chọn cả hai, giữa cùng phẩm chất đổi ngẫu nhiên giá trị tương đương'
	},
	[91006] = {
		id = 91006,
		fmt = '②Khi chọn [Loại giới hạn], chỉ giới hạn giữa cùng phẩm chất và cùng loại đổi ngẫu nhiên giá trị tương đương'
	},
	[91007] = {
		id = 91007,
		fmt = '③Khi chọn [Số hiệu giới hạn], chỉ giới hạn giữa cùng phẩm chất và cùng số hiệu đổi ngẫu nhiên giá trị tương đương'
	},
	[91008] = {
		id = 91008,
		fmt = '5. [Loại giới hạn] và [Số hiệu giới hạn] chỉ có thể chọn 1 trong 2'
	},
	[91009] = {
		id = 91009,
		fmt = '6.Càng đổi nhiều lần sẽ càng tốn vàng, chọn đổi Ấn phẩm chất cao sẽ tốn vàng nhiều hơn'
	},
	[91010] = {
		id = 91010,
		fmt = '7.Khi chọn Ấn đã cường hóa để đổi, vật liệu cường hóa cấp tương ứng sẽ được hoàn trả miễn phí'
	},
	[91011] = {
		id = 91011,
		fmt = '8.Trong màn đổi Ấn, chỉ hiển thị Ấn trong túi gốc có phẩm chất không thấp hơn tím và chưa khảm; Ấn đã khảm trên Ninja sẽ không hiển thị'
	},
	[92001] = {
		id = 92001,
		fmt = '1.Trong thời gian sự kiện, người chơi có thể dùng nguyên liệu thu thập được để gói bánh trong sự kiện Bánh lá thơm'
	},
	[92002] = {
		id = 92002,
		fmt = '2.Nguyên liệu chia 2 loại: nguyên liệu chính và nguyên liệu phụ, dùng #C0xF76B45#Vật phẩm Hộp quà nguyên liệu bánh#C0xFFFFFF# để nhận ngẫu nhiên, có thể nhận vật phẩm này từ sự kiện #C0xF76B45#Đăng nhập liên tục hoàn thành nhiệm vụ nhận nguyên liệu bánh#C0xFFFFFF# trong sự kiện giới hạn thời gian'
	},
	[92003] = {
		id = 92003,
		fmt = '3.Khi làm phải #C0xF76B45#cho nguyên liệu chính và nguyên liệu phụ cùng lúc, thiếu bất kỳ loại nào sẽ không thể làm bánh'
	},
	[92004] = {
		id = 92004,
		fmt = '4.Nguyên liệu chính và nguyên liệu phụ có thể #C0xF76B45#tự do phối trộn #C0xFFFFFF# để làm ra các vị bánh khác nhau'
	},
	[92005] = {
		id = 92005,
		fmt = '5.Sau khi có bánh có thể dùng trong màn sự kiện hoặc trong túi, nguyên liệu và bánh có thời hạn sử dụng, #C0xF76B45#vui lòng làm và ăn trong thời hạn quy định #C0xFFFFFF# hết hạn vật phẩm sẽ bị xóa'
	},
	[93001] = {
		id = 93001,
		fmt = '1.Câu cá có số lượt giới hạn mỗi ngày, số lượt reset lúc 05:00 mỗi ngày; dùng hết lượt thì hôm đó không thể câu nữa'
	},
	[93002] = {
		id = 93002,
		fmt = '2.Mỗi lần câu cá cần 1 mồi'
	},
	[93003] = {
		id = 93003,
		fmt = '3.Khi cá cắn câu, phải điều khiển để móc câu và cá chồng lên nhau, bấm/nhấn giữ để kéo móc lên, thả ra thì hạ xuống'
	},
	[93004] = {
		id = 93004,
		fmt = '4.Khi móc và cá chồng lên nhau, tiến độ câu cá tăng; nếu không chồng lên nhau, tiến độ giảm'
	},
	[93005] = {
		id = 93005,
		fmt = '5.Khi thanh tiến độ lên đến trên cùng thì câu thành công; nếu xuống đến dưới cùng thì câu thất bại; dù thành công hay thất bại, lượt và mồi đều sẽ bị tiêu hao'
	},
	[93006] = {
		id = 93006,
		fmt = '6.Chọn cần và mồi phẩm chất cao hơn để giảm độ khó thao tác hoặc tăng tỉ lệ câu cá tự động thành công'
	},
	[93007] = {
		id = 93007,
		fmt = '7.Tăng cấp câu cá sẽ nhận bonus trạng thái cho toàn bộ Ninja và giảm độ khó câu cá'
	},
	[93008] = {
		id = 93008,
		fmt = '8.Tăng cấp câu cá cần đạt số lượng đếm cá của cấp đó, đủ đếm sẽ tự động nâng cấp; sau khi nâng cấp, số đếm của cấp mới sẽ tính lại từ đầu'
	},
	[93009] = {
		id = 93009,
		fmt = '9.Có thể xuất hiện Ninja bí ẩn khác, các Ninja này không tính vào nâng cấp'
	},
	[93010] = {
		id = 93010,
		fmt = '10.Khi người chơi đạt Lv.68 sẽ có thể dùng chức năng câu cá tự động; bấm vào Ninja đồng hành trên màn để vào câu cá tự động, câu cá tự động có thể thất bại'
	},
	[93011] = {
		id = 93011,
		fmt = '11.Giải thích một số trạng thái liên quan đến câu cá:'
	},
	[93012] = {
		id = 93012,
		fmt = '①Tỉ lệ thành công câu cá tự động——tỉ lệ thành công của cá khi câu cá tự động phụ thuộc vào phẩm chất của chính nó, chịu ảnh hưởng bởi dụng cụ câu cá'
	},
	[93013] = {
		id = 93013,
		fmt = '②Tốc độ tăng tiến độ——trên màn câu cá, tốc độ tăng tiến độ bên phải khi móc câu và cá chồng lên nhau'
	},
	[93014] = {
		id = 93014,
		fmt = '③Tốc độ giảm tiến độ——trên màn câu cá, tốc độ giảm tiến độ bên phải khi móc câu và cá không chồng lên nhau'
	},
	[93015] = {
		id = 93015,
		fmt = '④Phạm vi phán định móc——kích thước khung phán định nơi móc câu nằm, chịu ảnh hưởng bởi mồi'
	},
	[93016] = {
		id = 93016,
		fmt = '⑤Thời gian chờ câu——thời gian phải chờ từ lúc thả câu đến khi cá cắn'
	},
	[93017] = {
		id = 93017,
		fmt = '⑥Phạm vi di chuyển của cá——khoảng cách cá trồi sụt trên màn câu cá'
	},
	[94001] = {
		id = 94001,
		fmt = '1.Giải câu cá được tổ chức mỗi 2 tuần, thời gian thi đấu là Chủ Nhật 05:00-23:00'
	},
	[94002] = {
		id = 94002,
		fmt = '2.Trong mỗi giải sẽ ghép ngẫu nhiên nhiều server để thi đấu, xếp hạng theo điểm câu cá nhận được'
	},
	[94003] = {
		id = 94003,
		fmt = '3.Khi giải kết thúc sẽ phát thưởng theo xếp hạng điểm cuối cùng'
	},
	[94004] = {
		id = 94004,
		fmt = '4.Người chơi có điểm bằng nhau xếp theo thời điểm đạt mốc'
	},
	[94005] = {
		id = 94005,
		fmt = '5.Trong giải sẽ có Kyogre hiếm xuất hiện, Kyogre có điểm cao hơn'
	},
	[94006] = {
		id = 94006,
		fmt = '6.Dùng mồi cao cấp chuyên dụng cho giải sẽ tăng cơ hội Kyogre xuất hiện'
	},
	[94007] = {
		id = 94007,
		fmt = '7.Chúc bạn đạt thành tích tốt'
	},
	[95001] = {
		id = 95001,
		fmt = '1.Ninja trong Sổ ảnh mới có thể Siêu tiến hóa tại Nhà Siêu tiến hóa'
	},
	[95002] = {
		id = 95002,
		fmt = '2.Sau Siêu tiến hóa, trạng thái cơ bản của Ninja tăng lên, toàn bộ trạng thái đã bồi dưỡng sẽ được kế thừa hoàn toàn, loại trạng thái và độ hiếm#C0xF76B45##L10#có thể thay đổi#C0xFFFFFF#'
	},
	[95003] = {
		id = 95003,
		fmt = '3.Ninja phải bồi dưỡng đến một cấp nhất định mới có thể Siêu tiến hóa, và dùng 2 loại vật phẩm chính đặc biệt là Đá then chốt và Đá Siêu tiến hóa chuyên dụng'
	},
	[95004] = {
		id = 95004,
		fmt = '4.Đá then chốt và Đá Siêu tiến hóa chuyên dụng có thể chuyển đổi mỗi ngày tại Nhà Siêu tiến hóa'
	},
	[95005] = {
		id = 95005,
		fmt = '5.Nhà Siêu tiến hóa sẽ định kỳ mở Ninja Siêu tiến hóa mới, xin hãy theo dõi'
	},
	[96001] = {
		id = 96001,
		fmt = '1.Đá then chốt có thể chuyển đổi bằng cách dùng#C0xF76B45##L10#Ninja cùng độ hiếm#C0xFFFFFF#hoặc#C0xF76B45##L10#Mảnh Ninja cùng độ hiếm#C0xFFFFFF# và có giới hạn số lần mỗi ngày:'
	},
	[96002] = {
		id = 96002,
		fmt = '①Ninja cấp A 1 con hoặc Ditto tím 1 con có thể đổi 10 Đá then chốt tiến hóa tím, Mảnh cấp A 3 mảnh có thể đổi 1 Đá then chốt tiến hóa tím'
	},
	[96003] = {
		id = 96003,
		fmt = '②Ninja cấp S 1 con hoặc Ditto cam 1 con có thể đổi 10 Đá then chốt tiến hóa cam, Mảnh cấp S 5 mảnh có thể đổi 1 Đá then chốt tiến hóa cam'
	},
	[96004] = {
		id = 96004,
		fmt = '③Ninja cấp S+ 1 con hoặc Ditto đỏ 1 con có thể đổi 10 Đá then chốt tiến hóa đỏ, Mảnh cấp S+ 8 mảnh có thể đổi 1 Đá then chốt tiến hóa đỏ'
	},
	[96005] = {
		id = 96005,
		fmt = '2.Mỗi ngày lúc 05:00 hệ thống sẽ cộng số lần đổi Đá then chốt mua bằng vàng, có thể tích lũy vĩnh viễn nhưng không vượt quá giới hạn tối đa'
	},
	[97001] = {
		id = 97001,
		fmt = '1.Đá Siêu chuyên dụng có thể chuyển đổi bằng cách dùng#C0xF76B45##L10#Ninja cùng trạng thái và độ hiếm#C0xFFFFFF#hoặc#C0xF76B45##L10#Mảnh Ninja cùng trạng thái và độ hiếm#C0xFFFFFF# และ có giới hạn số lần mỗi ngày:'
	},
	[97002] = {
		id = 97002,
		fmt = '①Ninja cấp A cùng trạng thái 1 con hoặc Ditto tím 1 con có thể đổi 10 Đá Siêu phẩm chất tím, Mảnh cấp A 3 mảnh có thể đổi 1 Đá Siêu phẩm chất tím'
	},
	[97003] = {
		id = 97003,
		fmt = '②Ninja cấp S cùng trạng thái 1 con hoặc Ditto cam 1 con có thể đổi 10 Đá Siêu phẩm chất cam, Mảnh cấp S 5 mảnh có thể đổi 1 Đá Siêu phẩm chất cam'
	},
	[97004] = {
		id = 97004,
		fmt = '③Ninja cấp S+ cùng trạng thái 1 con hoặc Ditto đỏ 1 con có thể đổi 10 Đá Siêu phẩm chất đỏ, Mảnh cấp S+ 8 mảnh có thể đổi 1 Đá Siêu phẩm chất đỏ 1 อัน'
	},
	[97005] = {
		id = 97005,
		fmt = '3.Với các loại Đá Siêu khác nhau, hệ thống sẽ ghi nhận số lần chuyển đổi riêng'
	},
	[97006] = {
		id = 97006,
		fmt = '4.Mỗi ngày lúc 05:00 hệ thống sẽ cộng số lần đổi Đá Siêu mua bằng vàng, có thể tích lũy vĩnh viễn nhưng không vượt quá giới hạn tối đa'
	},
	[98001] = {
		id = 98001,
		fmt = '1.Đấu trường đối chiến là#C0xF76B45#ghép cặp liên server#C0xFFFFFF# cần chờ ghép server, khi ghép thành công sẽ hiển thị#C0xF76B45#Trạng thái ghép cặp thành công chờ bắt đầu thi đấu'
	},
	[98002] = {
		id = 98002,
		fmt = '2.Đấu trường đối chiến chia theo mùa, quy trình mùa: #C0xF76B45#Thông báo mùa trước khi bắt đầu→Đang thi đấu→Kết thúc mùa hiển thị xếp hạng, mùa thường kéo dài nhiều tuần, có thể xem phía trên avatar của bạn'
	},
	[98003] = {
		id = 98003,
		fmt = '3.Trong mùa, luân phiên theo tuần; trong thời gian mở ghép cặp có thể ghép trận không giới hạn, khi không mở ghép cặp sẽ không thể thi đấu #C0xF76B45#Thời gian ghép cặp xem ở dưới nút bắt đầu ghép cặp'
	},
	[98004] = {
		id = 98004,
		fmt = '4.Đấu trường đối chiến là#C0xF76B45#ghép trận thời gian thực#C0xFFFFFF# mọi chế độ đều phải tự bấm bắt đầu ghép, chờ hệ thống ghép đối thủ phù hợp; khi đấu với đối thủ phải online chiến đấu suốt'
	},
	[98005] = {
		id = 98005,
		fmt = '5.Dùng#C0xF76B45#hệ thống điểm#C0xFFFFFF# tỉ lệ thắng càng cao điểm càng cao, BXH xếp theo điểm của toàn bộ người chơi tham gia; #C0xF76B45#điểm của 2 chế độ tính riêng và xếp hạng riêng'
	},
	[98006] = {
		id = 98006,
		fmt = '6.Mỗi lần mùa mới bắt đầu sẽ xóa kỷ lục điểm cao nhất lịch sử của mùa trước và điểm của 2 chế độ'
	},
	[99001] = {
		id = 99001,
		fmt = '1.Mở 2 chế độ trong Đấu trường đối chiến #C0xF76B45#là Chế độ không giới hạn và Chế độ công bằng#C0xFFFFFF#'
	},
	[99002] = {
		id = 99002,
		fmt = '2.Chế độ không giới hạn phải#C0xF76B45#thiết lập đội trước khi bắt đầu ghép#C0xFFFFFF# vào rồi phải tự điều khiển chiến đấu'
	},
	[99003] = {
		id = 99003,
		fmt = '3.Chế độ công bằng có lối chơi theo chủ đề, #C0xF76B45#chủ đề sẽ thay đổi mỗi tuần hoặc vài tuần (chỉ đổi chủ đề, điểm vẫn tích lũy)'
	},
	[99004] = {
		id = 99004,
		fmt = '4.Chế độ công bằng chia theo giai đoạn chọn Ninja trước khi chiến đấu thật là#C0xF76B45#hệ thống chọn vị trí và hệ thống ban-pick, khi điểm đạt mốc quy định sẽ tự chuyển sang ban-pick (chủ đề không đổi); xem điểm cụ thể bằng cách bấm i dưới nút chuyển trong Chế độ công bằng'
	},
	[99005] = {
		id = 99005,
		fmt = '5.Chế độ công bằng cần thiết lập đội dự bị trước, #C0xF76B45#số Ninja không đủ giới hạn tối thiểu sẽ không thể ghép trận; đội dự bị sẽ quyết định Ninja có thể dùng trong giai đoạn ban-pick'
	},
	[99006] = {
		id = 99006,
		fmt = '6.Chế độ đấu Không Giới Hạn và chế độ đấu Công Bằng dùng chế độ #C0xF76B45##L10#6V6#C0xFFFFFF# 1 trận, chế độ đấu Công Bằng sẽ điều chỉnh #C0xF76B45#các trạng thái#C0xFFFFFF# của ninja trong chiến đấu cho công bằng, ninja có độ hiếm khác nhau cũng sẽ được điều chỉnh về cùng một mặt bằng, trạng thái tốc độ của ninja sẽ quyết định thứ tự ra đòn trong chiến đấu'
	},
	[99007] = {
		id = 99007,
		fmt = '7.Trong chiến đấu chế độ đấu Công Bằng, #C0xF76B45#trạng thái và hiệu ứng của trang bị, rune và các thứ khác#C0xFFFFFF# sẽ không được tính vào, kỹ năng tổ chức, kỹ năng thiên phú, trạng thái thú triệu hồi và các thứ khác của hai bên sẽ được điều chỉnh bằng nhau'
	},
	[99008] = {
		id = 99008,
		fmt = '8.Chiến đấu ở chế độ đấu Không Giới Hạn và chế độ đấu Công Bằng dùng #C0xF76B45#chế độ tự điều khiển#C0xFFFFFF#, điều khiển kỹ năng ninja trong thời gian quy định, hết thời gian sẽ chuyển sang chiến đấu tự động'
	},
	[99009] = {
		id = 99009,
		fmt = '9.Chiến đấu ở chế độ đấu Không Giới Hạn và chế độ đấu Công Bằng tối đa 20 hiệp, trong chiến đấu nếu ninja một bên bị hạ hết thì thua, nếu hết hiệp vẫn chưa phân thắng bại thì bên có HP nhiều hơn sẽ thắng'
	},
	[100001] = {
		id = 100001,
		fmt = '1.Trong thời gian mở ghép cặp, #C0xF76B45#6 trận đầu mỗi ngày#C0xFFFFFF# sẽ nhận thưởng, thắng hay thua đều nhận thưởng'
	},
	[100002] = {
		id = 100002,
		fmt = '2.Trong mùa giải mỗi tuần có #C0xF76B45#phần thưởng mục tiêu nhỏ, nhận tại hộp quà góc dưới bên phải#C0xFFFFFF#, làm nhiệm vụ ghép cặp đơn giản là nhận được'
	},
	[100003] = {
		id = 100003,
		fmt = '3.Trong mùa giải #C0xF76B45#phát thưởng mỗi tuần, sau khi kết thúc ghép cặp Chủ Nhật 30 phút#C0xFFFFFF#, lấy điểm cao hơn trong 2 chế độ của người chơi để phát thưởng theo mốc, #C0xF76B45#Lưu ý: tham gia ghép cặp ít nhất 3 trận mỗi tuần (bất kỳ chế độ nào) mới nhận được thưởng'
	},
	[100004] = {
		id = 100004,
		fmt = '4.Kết thúc mùa giải #C0xF76B45#phát thưởng 1 lần, sau khi kết thúc ghép cặp ngày cuối cùng 30 phút#C0xFFFFFF#, lấy thứ hạng hiện tại cao nhất trong 2 chế độ của người chơi để phát thưởng theo thứ hạng, #C0xF76B45#Lưu ý: tham gia ghép cặp ít nhất 1 trận trong mùa giải (bất kỳ chế độ nào) mới nhận được thưởng'
	},
	[100005] = {
		id = 100005,
		fmt = '5.Xu hệ thống có thể dùng trong cửa hàng đấu trường, trong cửa hàng có hàng hóa cần mở khóa theo điều kiện, khi #C0xF76B45#đạt điều kiện điểm, hàng hóa sẽ được mở khóa vĩnh viễn ngay lập tức!'
	},
	[101001] = {
		id = 101001,
		fmt = '1.Trong thời gian sự kiện, người chơi quay lại có thể tìm #C0xF76B45#1 người chơi kỳ cựu#C0xFFFFFF# để liên kết tham gia sự kiện, #C0xF76B45#không có việc tranh giành liên kết'
	},
	[101002] = {
		id = 101002,
		fmt = '2.Người chơi kỳ cựu phải đạt cấp 55 và lực chiến 150,000 mới có thể cho người chơi quay lại liên kết'
	},
	[101003] = {
		id = 101003,
		fmt = '3.Sau khi hai bên liên kết, sẽ mở nội dung nhiệm vụ liên kết, nhiệm vụ chia thành nhiệm vụ chung và nhiệm vụ cá nhân, #C0xF76B45#mở toàn bộ nhiệm vụ cho người chơi quay lại, chỉ có một phần nhiệm vụ chung cần người chơi kỳ cựu tham gia, vì vậy ở trang sự kiện của người chơi kỳ cựu sẽ chỉ hiển thị nội dung nhiệm vụ chung'
	},
	[101004] = {
		id = 101004,
		fmt = '4.Mỗi lần hoàn thành nhiệm vụ, #C0xF76B45#cả hai bên đều nhận điểm nhiệm vụ#C0xFFFFFF#, khi điểm đạt một mức nhất định sẽ mở được rương tái ngộ, #C0xF76B45#tiến độ rương của hai bên giống nhau, cần cùng cố gắng để mở!'
	},
	[101005] = {
		id = 101005,
		fmt = '5.Cả hai bên #C0xF76B45#chỉ có thể liên kết 1 lần để tham gia sự kiện này #C0xFFFFFF#sau khi kết thúc sự kiện tái ngộ, người chơi kỳ cựu sẽ vào thời gian hồi, tức là không thể tham gia lại sự kiện tái ngộ trong một khoảng thời gian'
	},
	[101006] = {
		id = 101006,
		fmt = '6.Nếu sự kiện tái ngộ lần này không hoàn thành do người chơi quay lại lâu không đăng nhập, người chơi kỳ cựu đã liên kết, sau khi kết thúc sự kiện tái ngộ lần này sẽ có thời gian hồi ngắn hơn'
	},
	[101007] = {
		id = 101007,
		fmt = '7.Sau khi kết thúc sự kiện, #C0xF76B45#phần thưởng trong sự kiện này chưa nhận sẽ không gửi thêm mail #C0xFFFFFF#có thưởng thì mau nhận!'
	},
