		fmt = '3.Mỗi ngày 05:00 hệ thống sẽ tăng một ít điểm buff, có thể mua bằng vàng, số lần mua mỗi ngày có giới hạn, vượt Dojo cũng sẽ nhận điểm buff'
	},
	[102017] = {
