	},
	[102018] = {
		id = 102018,
		fmt = '#C0xF76B45#【Ví dụ phần thưởng Chủ Dojo】'
	},
	[103001] = {
		id = 103001,
		fmt = '1.Dojo liên server cũng có 8 Dojo khác nhau, và mỗi Dojo liên server có thể có 1 Chủ Dojo liên server và 7 Thành Viên liên server'
	},
	[103002] = {
		id = 103002,
		fmt = '2.Sau khi vượt qua toàn bộ độ khó của ải Dojo trong server, có thể khiêu chiến trở thành Chủ Dojo Vinh Dự hoặc Thành Viên liên server'
