	},
	[103005] = {
		id = 103005,
		fmt = '5.Khiêu chiến Chủ Dojo liên server cần có ninja trạng thái chỉ định, nếu không có ninja trạng thái hạn chế thì không thể khiêu chiến'
	},
	[103006] = {
		id = 103006,
		fmt = '#C0xF76B45#【Ví dụ phần thưởng Dojo liên server】'
	},
	[104001] = {
		id = 104001,
		fmt = '1.Trong thời gian sự kiện, có thể chơi game lật thẻ để nhận vật phẩm đã lật'
	},
	[104002] = {
		id = 104002,
		fmt = '2.Sự kiện thiết lập nhiều vòng lật thẻ, mỗi vòng có 1 phần thưởng lớn đặc biệt, phần thưởng lớn có thể nằm dưới bất kỳ lá thẻ nào, lật sẽ nhận ngay và bắt đầu vòng tiếp theo'
	},
	[104003] = {
		id = 104003,
		fmt = '3.Lật thẻ sẽ tiêu hao lượt, dùng lượt miễn phí trước, lượt miễn phí reset mỗi ngày lúc 5 giờ, sau đó dùng lượt nhiệm vụ, lượt nhiệm vụ không reset, nhận từ việc hoàn thành nhiệm vụ'
	},
	[104004] = {
		id = 104004,
		fmt = '4.Nội dung phần thưởng lớn đặc biệt của mỗi vòng lật thẻ sẽ hiển thị theo thứ tự trong trang sự kiện, chúc may mắn!'
	},
	[105001] = {
		id = 105001,
		fmt = '1.Khi đạt điều kiện, chủ phòng có thể yêu cầu người chơi khác rời phòng, người chơi khác cũng có thể bỏ phiếu cho chủ phòng rời phòng'
	},
	[105002] = {
		id = 105002,
		fmt = '2.Phải thỏa 3 điều kiện sau: một, có ít nhất 3 người chơi hoàn thành khiêu chiến trong phòng; hai, người bị yêu cầu rời phòng ở trong phòng ít nhất 3 giờ; ba, người đó có số lần khiêu chiến thành công 0 lần hoặc chưa khiêu chiến'
	},
	[105003] = {
		id = 105003,
		fmt = '3.Khi chủ phòng yêu cầu người chơi rời phòng, bản thân phải khiêu chiến thành công ít nhất 1 lần'
	},
	[105004] = {
		id = 105004,
		fmt = '4.Khi người chơi khác bỏ phiếu cho chủ phòng rời phòng, bản thân phải hoàn thành 3 lần mới có quyền bỏ phiếu, và kết quả bỏ phiếu phải có số phiếu cho rời nhiều hơn số phiếu cho ở lại, mới có thể yêu cầu chủ phòng rời phòng'
	},
	[105005] = {
		id = 105005,
		fmt = '5.Người bị yêu cầu rời phòng tích lũy 3 lần trước khi reset khiêu chiến sẽ không thể tham gia khiêu chiến Ảo Ảnh lần này, khi bắt đầu lần khiêu chiến tiếp theo thì sẽ vào lại bình thường'
	},
	[106001] = {
		id = 106001,
		fmt = '1.Trong thời gian sự kiện, mảnh cùng phẩm chất có thể chuyển đổi lẫn nhau, sau khi chuyển đổi thành công mảnh trong túi sẽ bị tiêu hao và nhận mảnh đã chọn'
	},
	[106002] = {
		id = 106002,
		fmt = '2.Mỗi vòng sự kiện, số lượng mảnh phẩm chất khác nhau có thể chuyển đổi được tính riêng và có giới hạn số lần chuyển đổi'
	},
	[106003] = {
		id = 106003,
		fmt = '3.Khi cấp VIP của người chơi tăng đến một mức nhất định, có thể tăng thêm số lần chuyển đổi'
	},
	[106004] = {
		id = 106004,
		fmt = '4.Mảnh có thể chuyển đổi trong mỗi vòng sự kiện sẽ khác nhau, nếu vòng này không có mảnh bạn muốn chuyển, hãy chờ sự kiện lần sau!'
	},
	[107001] = {
		id = 107001,
		fmt = '1.Với mỗi boss lễ hội, mỗi người chỉ có thể khiêu chiến 1 lần'
	},
	[107002] = {
		id = 107002,
		fmt = '2.Mỗi ải lễ hội có giới hạn số lần khiêu chiến, đạt giới hạn sẽ không thể khiêu chiến nữa'
	},
	[107003] = {
		id = 107003,
		fmt = '3.Bản thân có thể khiêu chiến boss lễ hội do mình phát hiện 1 lần, lần khiêu chiến này không tính vào số lần khiêu chiến của người khác'
	},
	[107004] = {
		id = 107004,
		fmt = '4.Ải lễ hội có 3 mức độ khó, mức cao nhất là SSS'
	},
	[107005] = {
		id = 107005,
		fmt = '5.Mỗi boss lễ hội có đếm ngược riêng, khi đếm ngược kết thúc dữ liệu khiêu chiến sẽ biến mất ngay'
	},
	[107006] = {
		id = 107006,
		fmt = '6.Khiêu chiến thắng sẽ nhận thưởng, khiêu chiến thua không có thưởng và không trừ số lần khiêu chiến'
	},
	[107007] = {
		id = 107007,
		fmt = '7.Mỗi người mỗi ngày có giới hạn số boss Halloween phát sinh và hồi kích hoạt'
	},
	[108001] = {
		id = 108001,
		fmt = '1.Mỗi ngày đến thời gian chỉ định sẽ mở mini game Hồng Bao rơi từ trời, người chơi tham gia mini game sẽ nhận 1 vé cào, có cơ hội trúng phần thưởng lớn đặc biệt'
	},
	[108002] = {
		id = 108002,
		fmt = '2.Mini game Hồng Bao rơi từ trời mở mỗi ngày theo thời gian chỉ định, hãy chú ý nội dung hiển thị ở trang chính sự kiện, hết giờ sẽ đóng và sẽ không nhận vé cào của lượt này'
	},
	[108003] = {
		id = 108003,
		fmt = '3.Mini game Hồng Bao rơi từ trời yêu cầu người chơi click vào vật phẩm hồng bao rơi trên màn hình trong thời gian quy định, khi hết giờ click được bao nhiêu nhận bấy nhiêu, vật phẩm hồng bao có thể mở trong túi để nhận thưởng'
	},
	[108004] = {
		id = 108004,
		fmt = '4.Mỗi lượt mini game Hồng Bao rơi từ trời sẽ rơi loại hồng bao không hoàn toàn giống nhau, hãy chú ý nội dung hiển thị ở trang chính sự kiện'
	},
	[108005] = {
		id = 108005,
		fmt = '5.Sau khi nhận vé cào có thể đến lối vào vé cào để cào thưởng, phần thưởng vé cào cũng hiển thị tại lối vào đó'
	},
	[108006] = {
		id = 108006,
		fmt = '6.Sau khi trúng thưởng, nội dung trúng thưởng sẽ được gửi dần qua mail khi lượt mini game Hồng Bao rơi từ trời này kết thúc, người chơi trúng thưởng hãy chú ý mail'
	},
	[108007] = {
		id = 108007,
		fmt = '7.Nếu người chơi đã nhận vé cào nhưng không kịp cào trước khi lượt mini game Hồng Bao rơi từ trời này kết thúc, hệ thống sẽ tự động cào và xác định trúng thưởng, và gửi mail phần thưởng đúng giờ vào hòm thư'
	},
	[109001] = {
		id = 109001,
		fmt = '1.Sự kiện là mini game nặn người tuyết, người tuyết có cấp, theo cấp tăng lên sẽ mở khóa trang trí và tùy biến bộ phận người tuyết'
	},
	[109002] = {
		id = 109002,
		fmt = '2.Thu thập vật phẩm Bông Tuyết giới hạn sự kiện, có thể dùng để nặn Pikachu người tuyết, mỗi lần dùng 1 vật phẩm để nặn sẽ nhận 1 lần thưởng ngẫu nhiên, đồng thời Pikachu sẽ tăng cấp'
	},
	[109003] = {
		id = 109003,
		fmt = '3.Sau khi cấp Pikachu tăng lên sẽ mở khóa một số trang trí Giáng Sinh trên người, phần đã mở có thể tự do đổi màu trang trí ưa thích, đồng thời sẽ mở khóa một số trang trí môi trường không khí Giáng Sinh'
	},
	[109004] = {
		id = 109004,
		fmt = '4.Cấp Pikachu có giới hạn tối đa, khi đạt giới hạn tối đa nghĩa là toàn bộ trang trí và tùy biến đều đã hiển thị và mở hết, nhưng lúc này vẫn có thể dùng vật phẩm Bông Tuyết với nó, mỗi lần dùng vẫn nhận thưởng như thường'
	},
	[110001] = {
		id = 110001,
		fmt = '1.Mini game cho chọn 3 ninja có HP, tốc độ di chuyển và kích thước khác nhau, trước mỗi lần vào game có thể tự do chọn ninja sở trường để vào game'
	},
	[110002] = {
		id = 110002,
		fmt = '2.Sau khi game bắt đầu, bóng tuyết và hộp quà sẽ rơi từ trời, trúng mỗi bóng tuyết sẽ giảm 1 HP, nhặt hộp quà được điểm, khi hết thời gian hoặc bị bóng tuyết làm hết HP thì game kết thúc'
	},
	[110003] = {
		id = 110003,
		fmt = '3.#C0xF76B45#Bóng tuyết rơi rất nhanh, chú ý bóng dưới chân, hộp quà rơi xuống đất sẽ biến mất không lâu sau đó, phải nhanh tay nhặt, nhặt được thì có điểm, ninja ở sân càng lâu càng nhận nhiều bonus điểm'
	},
	[110004] = {
		id = 110004,
		fmt = '4.Mỗi ngày mini game mở miễn phí theo số lượt, có thể dùng vàng mua thêm số lượt chơi'
	},
	[110005] = {
		id = 110005,
		fmt = '5.Mini game có bảng xếp hạng, điểm cao nhất mỗi ván của bạn sẽ được xếp hạng hiển thị'
	},
	[110006] = {
		id = 110006,
		fmt = '6.Điểm nhận được từ mỗi ván của mini game sẽ được tích lũy ghi nhận, đạt mốc điểm sẽ nhận phần thưởng tương ứng'
	},
	[111001] = {
		id = 111001,
		fmt = '1.Bồi dưỡng Bát Quái có thể tăng trạng thái cho tất cả ninja, mau đi khiêu chiến Dojo để nhận vật liệu bồi dưỡng!'
	},
	[111002] = {
		id = 111002,
		fmt = '2.Số Bát Quái bằng với số Dojo, mặc định mở 4 cái, khi ô Bát Quái sáng đến một cấp nhất định sẽ mở khóa loại Bát Quái mới'
	},
	[111003] = {
		id = 111003,
		fmt = '3.Mỗi Bát Quái cần bố trí ninja hộ vệ, tùy theo tình trạng bồi dưỡng, ninja hộ vệ sẽ cho thêm bonus trạng thái Bát Quái'
	},
	[111004] = {
		id = 111004,
		fmt = '4.Sau khi Bát Quái thức tỉnh lên cấp cao hơn, có thể mở thêm ô ninja hộ vệ mới'
	},
	[112001] = {
		id = 112001,
		fmt = '#C0xF76B45##L10#【Quy tắc cơ bản】'
	},
	[112002] = {
		id = 112002,
		fmt = '1.Thời gian mở Hỏi Đáp Ninja: #C0xF76B45#Thứ Bảy 5:00#C0xFFFFFF# đến #C0xF76B45#Chủ Nhật 24:00#C0xFFFFFF#, mở mỗi 2 tuần'
	},
	[112003] = {
		id = 112003,
		fmt = '2.Sau khi mở Hỏi Đáp Ninja, có 1 lần miễn phí vào trả lời, vào trả lời sẽ trừ lượt #C0xF76B45#(thoát giữa chừng cũng tính dùng 1 lượt)#C0xFFFFFF#, ngày hôm sau 05:00 reset'
	},
	[112004] = {
		id = 112004,
		fmt = '3.Mỗi ngày có thể dùng vàng mua thêm 1 lượt trả lời, nhưng trong 2 lượt chỉ lấy điểm cao hơn để lên bảng xếp hạng'
	},
	[112005] = {
		id = 112005,
		fmt = '4.Thành tích Thứ Bảy/Chủ Nhật sẽ hiển thị trên bảng xếp hạng, thành viên tổ chức xem được hạng của mình và tổ chức đang ở'
	},
	[112006] = {
		id = 112006,
		fmt = '#C0xF76B45##L10#【Quy tắc trả lời】'
	},
	[112007] = {
		id = 112007,
		fmt = '1.Tổng cộng có 15 câu hỏi, trả sai hoặc không trả lời được 0 điểm, trả đúng sẽ được điểm tương ứng, trả đúng và nhanh sẽ được điểm cao hơn'
	},
	[112008] = {
		id = 112008,
		fmt = '2.Mỗi câu có 15 giây trả lời, khi đếm ngược kết thúc hoặc người chơi xác nhận đáp án trước sẽ tự động vào câu tiếp theo'
	},
	[112009] = {
		id = 112009,
		fmt = '3.Câu hỏi chia thành câu chữ, câu hình, câu mini game, khi gặp mini game lần đầu sẽ có giải thích quy tắc liên quan'
	},
	[112010] = {
		id = 112010,
		fmt = '4.Điểm là tiêu chí xếp hạng bảng xếp hạng, hạng tổ chức là tổng điểm của toàn bộ người chơi trong tổ chức để xếp hạng (người chơi rời tổ chức, điểm đã đạt vẫn ghi cho tổ chức cũ)'
	},
	[112011] = {
		id = 112011,
		fmt = '#C0xF76B45##L10#【Quy tắc thưởng trả lời】'
	},
	[112012] = {
		id = 112012,
		fmt = 'Mỗi lần người trả lời đúng 1 câu sẽ nhận 1 túi thưởng, nhận tối đa 15 túi, chờ trả lời xong rồi mở cùng lúc'
	},
	[112013] = {
		id = 112013,
		fmt = '#C0xF76B45##L10#【Quy tắc thưởng hạng tổ chức】'
	},
	[112101] = {
		id = 112101,
		fmt = '#C0xF76B45##L10#【Quy tắc thưởng hạng cá nhân】'
	},
	[113001] = {
		id = 113001,
		fmt = '1.Phố Thương Mại liên server cần chờ ghép cặp giữa các server, khi ghép cặp thành công sẽ hiển thị #C0xF76B45#trạng thái ghép cặp thành công chờ bắt đầu thi đấu#C0xFFFFFF# trên màn hình'
	},
	[113002] = {
		id = 113002,
		fmt = '2.Quy trình mùa giải: #C0xF76B45#Công bố mùa giải(1 ngày)——Bắt đầu mùa giải(10:00 ngày hôm sau, kéo dài 3 ngày)——Hiển thị kết quả mùa giải(ngày kết thúc 22:00 đến trước ngày bắt đầu lần sau)'
	},
	[113003] = {
		id = 113003,
		fmt = '3.Trong mùa giải #C0xF76B45#mỗi ngày 22:00 và ngày kết thúc mùa giải 22:00#C0xFFFFFF# sẽ phát thưởng cá nhân theo thứ hạng, #C0xF76B45#ngày kết thúc mùa giải 22:00#C0xFFFFFF# sẽ tính thưởng server, #C0xF76B45#tất cả nội dung nhận qua mail'
	},
	[113004] = {
		id = 113004,
		fmt = '4.Trong mùa giải, #C0xF76B45#đấu giá chỉ được thực hiện mỗi ngày 10:00-22:00, thời gian khác là giai đoạn nghỉ chiến, trong giai đoạn nghỉ chiến cửa hàng đóng, không thể đấu giá, báo thù và chiến đấu khác'
	},
	[113005] = {
		id = 113005,
		fmt = '5.Người chơi có số lần đấu giá miễn phí, số lần refresh người chơi để đấu giá, và số lần báo thù, vượt số lần có thể dùng vàng hoặc xu vàng để mua'
	},
	[113006] = {
		id = 113006,
		fmt = '6.Khu phố thương mại chia theo thứ hạng thành #C0xF76B45#khu cao cấp và khu thường#C0xFFFFFF#, hạng 1-10 sẽ ở khu cao cấp, các hạng khác hiển thị ở khu thường'
	},
	[113007] = {
		id = 113007,
		fmt = '8.Trong dữ liệu chiến tranh có thể xem video chiến đấu giữa người chơi cao cấp trong thời gian gần đây'
	},
	[113008] = {
		id = 113008,
		fmt = '9.Trong mùa giải #C0xF76B45#mỗi ngày và khi kết thúc mùa giải lúc 22:00 sẽ tính toán#C0xFFFFFF# và phát chức vị theo thứ hạng tính toán, chức vị sẽ do #C0xF76B45#3 người chơi top đầu bảng xếp hạng#C0xFFFFFF# nhận, trong mùa giải #C0xF76B45#chức vị tính theo ngày có hiệu lực đến lần tính theo ngày tiếp theo, chức vị tính khi kết thúc mùa giải có hiệu lực đến thời gian chuẩn bị ghép cặp mùa giải tiếp theo'
	},
	[113020] = {
		id = 113020,
		fmt = '1.Thứ hạng có tốc độ sản xuất Xu Tài Nguyên và điểm bonus tương ứng, sau khi chiếm giữ thứ hạng đó, #C0xF76B45#Xu Tài Nguyên sẽ được sản xuất theo tốc độ hiện tại và sẽ có điểm bonus của thứ hạng này, sau khi đổi thứ hạng sẽ thay trực tiếp tốc độ sản xuất và điểm bonus, không cộng dồn'
	},
	[113021] = {
		id = 113021,
		fmt = '2.Xu Tài Nguyên sản xuất cả ngày theo tốc độ của thứ hạng đang giữ, bao gồm cả thời gian không phải nghỉ chiến, đấu giá với người chơi sẽ cướp được một phần Xu Tài Nguyên của họ, #C0xF76B45#có thể dùng để mua vật phẩm cửa hàng và bồi dưỡng trạng thái trong Chúc Phúc'
	},
	[113022] = {
		id = 113022,
		fmt = '3.Điểm dựa vào việc hoán đổi thứ hạng, và phần thưởng chiến đấu/tiêu diệt trong chiến tranh boss giới hạn thời gian sản xuất, #C0xF76B45#điểm dùng khi tính mùa giải#C0xFFFFFF# lấy tổng điểm của 100 người chơi top đầu mỗi server để xếp thứ tự'
	},
	[113040] = {
		id = 113040,
		fmt = '1.Trước khi chiến đấu, người chơi có thể #C0xF76B45#xếp 3 đội, mỗi đội tối đa ra sân 4 ninja'
	},
	[113041] = {
		id = 113041,
		fmt = '2.Chiến đấu dùng chế độ tính điểm theo từng đội, #C0xF76B45#3 ván thắng 2 là thắng chung cuộc, tối đa đánh 3 hiệp, kết quả hiệp trước không ảnh hưởng hiệp sau'
	},
	[113042] = {
		id = 113042,
		fmt = '3.2 đội ninja của một bên bị đánh bại hết sẽ thua, nếu hết hiệp đội nhỏ vẫn chưa phân thắng bại, #C0xF76B45#quyết định đội nhỏ bên phòng thủ thắng hiệp này'
	},
	[113043] = {
		id = 113043,
		fmt = '4.Cách chiến đấu Phố Thương Mại liên server là #C0xF76B45#khóa tự động chiến đấu#C0xFFFFFF#'
	},
	[113044] = {
		id = 113044,
		fmt = '5.Khi đối thủ khiêu chiến người chơi, sẽ dùng đội phòng thủ của người chơi để chiến đấu'
	},
	[113080] = {
		id = 113080,
		fmt = '1.Người chơi bắt đầu đấu giá, nếu #C0xF76B45#chiến đấu thắng sẽ hoán đổi vị trí với người chơi có hạng cao hơn mình và kế thừa tốc độ sản xuất cùng điểm bonus của hạng mới, đồng thời nhận một phần Xu Tài Nguyên của đối thủ, nếu đánh với đối thủ hạng thấp hơn sẽ không đổi hạng và nội dung liên quan, chỉ nhận một phần Xu Tài Nguyên của đối thủ'
	},
	[113081] = {
		id = 113081,
		fmt = '2.Khi đối thủ bắt đầu chiến đấu và chiến đấu thành công, có thể báo thù, #C0xF76B45#báo thù cùng một mục tiêu có giới hạn số lần, báo thù cũng nhận một phần Xu Tài Nguyên của mục tiêu nhưng không đổi hạng, và có thể kích hoạt báo thù của mục tiêu với bản thân'
	},
	[113082] = {
		id = 113082,
		fmt = '3.Khi xảy ra các tình huống sau, dù mục tiêu đấu giá hoặc báo thù thành công cũng không thể nhận Xu Tài Nguyên:'
	},
	[113083] = {
		id = 113083,
		fmt = '#C0xF76B45#①đạt giới hạn số lần bị đấu giá trong 1 giờ, lần cuối bị chiến đấu cách hiện tại hơn 1 giờ sẽ hủy trạng thái này'
	},
	[113084] = {
		id = 113084,
		fmt = '#C0xF76B45#②khi lực chiến hai bên đạt một tỷ lệ nhất định của chênh lệch lực chiến'
	},
	[113085] = {
		id = 113085,
		fmt = '#C0xF76B45#③hai bên là người chơi cùng server'
	},
	[113086] = {
		id = 113086,
		fmt = '#C0xF76B45#④đạt giới hạn số lần bị đấu giá mỗi ngày'
	},
	[113087] = {
		id = 113087,
		fmt = '4.Mục tiêu bị đấu giá (cướp Xu Tài Nguyên) hoặc bị báo thù thành công sẽ nhận #C0xF76B45#bảo hộ chống đấu giá 5 phút, trong 5 phút sẽ không bị chiến đấu nữa'
	},
	[114001] = {
		id = 114001,
		fmt = '1.Trong thời gian chơi liên tục, sẽ refresh boss Team Rocket có thể khiêu chiến ở khu phố thương mại thường'
	},
	[114002] = {
		id = 114002,
		fmt = '2.Thời gian refresh boss là trưa 12:30 và chiều 18:30, mỗi khung giờ boss có độ khó khác nhau'
	},
	[114003] = {
		id = 114003,
		fmt = '3.Mỗi người chơi có số lần khiêu chiến boss miễn phí, có thể mua thêm số lần'
	},
	[114004] = {
		id = 114004,
		fmt = '4.Mỗi lần người chơi khiêu chiến xong sẽ trừ HP boss tương ứng và nhận thưởng ngẫu nhiên, người kết liễu cuối cùng nhận thêm thưởng kết liễu, sau khi boss bị hạ sẽ phát thưởng xếp hạng theo sát thương gây ra cao thấp'
	},
	[114005] = {
		id = 114005,
		fmt = '5.Server nơi người chơi kết liễu boss sẽ nhận bonus thêm, có 3 hiệu ứng: tăng trạng thái, tăng sản lượng, tăng cướp đoạt, một trong các hiệu ứng'
	},
	[114006] = {
		id = 114006,
		fmt = '6.Boss buổi tối sẽ cực mạnh, sau khi boss bị hạ người chơi ở server của người kết liễu sẽ nhận bonus siêu ngầu đặc biệt'
	},
	[115001] = {
		id = 115001,
		fmt = '1.Sự kiện giới hạn năm mới Tụ Phúc Online! Trong thời gian sự kiện, hoàn thành nhiệm vụ nhận rất nhiều phần thưởng!'
	},
	[115002] = {
		id = 115002,
		fmt = '2.Trong thời gian sự kiện có 16 nhiệm vụ tích lũy tiến độ, mỗi nhiệm vụ có số, số tương ứng với số ô ghép bí ẩn bên phải'
	},
	[115003] = {
		id = 115003,
		fmt = '3.Mỗi lần hoàn thành nhiệm vụ đúng số, có thể nhận thưởng nhiệm vụ, đồng thời thẻ tương ứng sẽ được mở'
	},
	[115004] = {
		id = 115004,
		fmt = '4.Góc dưới bên phải của ô ghép hiển thị 8 túi phúc, hoàn thành nhiệm vụ theo đường thẳng tương ứng, mở thẻ nhận thưởng túi phúc'
	},
	[115005] = {
		id = 115005,
		fmt = '5.Sau khi mở đủ 16 thẻ ô ghép, có thể nhận thưởng túi phúc khổng lồ!'
	},
	[116001] = {
		id = 116001,
		fmt = '1.Trong thời gian sự kiện, mỗi ngày có số lần giới hạn vào mini game xây nhà chọc trời để chơi'
	},
	[116002] = {
		id = 116002,
		fmt = '2.Mini game yêu cầu trong một thời gian thao tác, #C0xF76B45#cố gắng đặt tầng xây dựng được hoàn chỉnh để hoàn thành xây tòa nhà cao, mỗi ván có 3 lần xây, phải dùng hợp lý'
	},
	[116003] = {
		id = 116003,
		fmt = '3.Trong quá trình xây, sẽ #C0xF76B45#ngẫu nhiên xuất hiện thưởng xây dựng, nếu xây tầng này thành công sẽ nhận thưởng đó #C0xFFFFFF#phần thưởng sẽ được thống kê hiển thị khi tổng kết ván cuối'
	},
	[116004] = {
		id = 116004,
		fmt = '4.Xây dựng còn có đánh giá điểm xây dựng, #C0xF76B45#tầng càng cao, xây càng hoàn chỉnh, điểm càng cao'
	},
	[116005] = {
		id = 116005,
		fmt = '5.Điểm mỗi ván mini game nhà chọc trời, số tầng xây, số lần xuất hiện xây hoàn chỉnh sẽ được tích lũy ghi nhận trong nhiệm vụ huy hiệu, #C0xF76B45#hoàn thành nhiệm vụ tương ứng nhận thưởng nhiệm vụ và điểm huy hiệu, nâng cấp huy hiệu cũng nhận thưởng nâng cấp'
	},
	[116006] = {
		id = 116006,
		fmt = '6.Bảng xếp hạng hiển thị thành tích người chơi trong nhiều server, xếp theo điểm xây dựng và số tầng xây'
	},
	[117001] = {
		id = 117001,
		fmt = '1.Hoàn thành nhiệm vụ hằng ngày nhận Nhiệt Huyết, Nhiệt Huyết tích lũy càng cao, phần thưởng Mật Lệnh mở khóa càng nhiều'
	},
	[117002] = {
		id = 117002,
		fmt = '2.Mua Mật Lệnh bản Cao Cấp có thể mở thêm phần thưởng đặc biệt siêu lời'
	},
	[117003] = {
		id = 117003,
		fmt = '3.Mật Lệnh bản Cao Cấp mua mỗi kỳ chỉ có hiệu lực trong kỳ sự kiện này, kỳ sau phải mua lại, Nhiệt Huyết tích lũy cũng sẽ bị xóa về 0 khi sự kiện kết thúc'
	},
	[117004] = {
		id = 117004,
		fmt = '4.Khi sự kiện Mật Lệnh kết thúc, toàn bộ phần thưởng chưa nhận sẽ được gửi qua mail'
	},
	[118001] = {
		id = 118001,
		fmt = '1.Mỗi ngày vượt Huấn Luyện Anbu, tích lũy số tầng đã qua (mỗi tầng phải khiêu chiến xong boss cuối mới tính) có thể mở khóa nhiều phần thưởng Mật Lệnh'
	},
	[118002] = {
		id = 118002,
		fmt = '2.Mua Mật Lệnh bản Cao Cấp có thể mở thêm phần thưởng đặc biệt siêu lời'
	},
	[118003] = {
		id = 118003,
		fmt = '3.Mật Lệnh bản Cao Cấp mua mỗi kỳ chỉ có hiệu lực trong kỳ sự kiện này, kỳ sau phải mua lại, số tầng đã qua tích lũy cũng sẽ bị xóa về 0 khi sự kiện kết thúc'
	},
	[118004] = {
		id = 118004,
		fmt = '4.Khi sự kiện Mật Lệnh kết thúc, toàn bộ phần thưởng chưa nhận sẽ được gửi qua mail'
	},
	[119001] = {
		id = 119001,
		fmt = '#C0xFFFFFFFF#1.Mỗi tuần khiêu chiến ải Dojo thành công có thể tích lũy số lần khiêu chiến (#C0xF76B45#khiêu chiến người chơi Dojo không tính lượt#C0xFFFFFFFF#), số lần khiêu chiến tích lũy càng nhiều, phần thưởng Mật Lệnh mở khóa càng nhiều'
	},
	[119002] = {
		id = 119002,
		fmt = '2.Mua Mật Lệnh bản Cao Cấp có thể mở thêm phần thưởng đặc biệt siêu lời'
	},
	[119003] = {
		id = 119003,
		fmt = '3.Mật Lệnh bản Cao Cấp mua mỗi kỳ chỉ có hiệu lực trong kỳ sự kiện này, kỳ sau phải mua lại, số lần khiêu chiến ải tích lũy cũng sẽ bị xóa về 0 khi sự kiện kết thúc'
	},
	[119004] = {
		id = 119004,
		fmt = '4.Khi sự kiện Mật Lệnh kết thúc, toàn bộ phần thưởng chưa nhận sẽ được gửi qua mail'
	},
	[120001] = {
		id = 120001,
		fmt = '1.Gieo xúc xắc để di chuyển, trên bản đồ có rương báu #C0xF76B45#thưởng nhiều, và sau khi nhận sẽ ngẫu nhiên xuất hiện lại trên bản đồ, hãy đặt truy đuổi rương báu làm mục tiêu của bạn!'
	},
	[120002] = {
		id = 120002,
		fmt = '2.Khi đi trên bản đồ, còn sẽ gặp các ô sự kiện khác, trên màn hình bản đồ #C0xF76B45#click ô sự kiện có thể xem mô tả riêng'
	},
	[120003] = {
		id = 120003,
		fmt = '3.Trong ô sự kiện, #C0xF76B45#cửa hàng nhỏ và rương báu chỉ cần đi qua là kích hoạt sự kiện #C0xFFFFFF#sau khi sự kiện kết thúc, nếu người chơi vẫn có thể di chuyển thì sẽ tiếp tục đi tới, #C0xF76B45#các ô sự kiện khác phải dừng lại mới kích hoạt'
	},
	[120004] = {
		id = 120004,
		fmt = '4.Trong Đại Phiêu Lưu, bạn sẽ nhận #C0xF76B45#Huy Hiệu Nhà Phiêu Lưu #C0xFFFFFF#nó cho phép bạn #C0xF76B45#đi qua cửa hàng nhỏ để mua vật phẩm, lưu ý, nó chỉ dùng để mua vật phẩm dùng được trong Đại Phiêu Lưu'
	},
	[120005] = {
		id = 120005,
		fmt = '5.Trong quá trình phiêu lưu sẽ nhận thẻ vật phẩm và xúc xắc có đặc tính khác nhau, nếu không biết công dụng của chúng, #C0xF76B45#có thể xem mô tả vật phẩm bên dưới'
	},
	[121001] = {
		id = 121001,
		fmt = '#L10##C0xF76B45#Luôn nắm tay nhau, năm nay hoa đẹp hơn năm ngoái #C0xFFFFFFFF#——người chơi khắp thế giới dẫn ninja của họ, bắt đầu mùa giải chạy đua ninja thường niên'
	},
	[121002] = {
		id = 121002,
		fmt = 'Mùa giải chạy đua ninja gồm: Dự đoán có thưởng, Chuẩn bị trước trận, Đang thi đấu, Công bố kết quả 4 giai đoạn'
	},
	[121003] = {
		id = 121003,
		fmt = '#L10##C0xF76B45#【Dự đoán có thưởng】:'
	},
	[121004] = {
		id = 121004,
		fmt = '1.Trong thời gian mở sự kiện, mùa giải chạy đua ninja mỗi ngày 2 lượt (12:00 và 20:00), mỗi lượt sẽ ngẫu nhiên chọn 4 ninja tham gia chạy'
	},
	[121005] = {
		id = 121005,
		fmt = '2.Người chơi dù không thể tham gia luyện tập cùng ninja, vẫn có thể dự đoán có thưởng trước khi trận đấu bắt đầu, kết quả dự đoán sẽ công bố khi trận đấu kết thúc'
	},
	[121006] = {
		id = 121006,
		fmt = '3.Thời gian dự đoán có thưởng: mỗi ngày 05:00~11:57 và 13:00~19:57, các thời gian khác không thể dự đoán'
	},
	[121007] = {
		id = 121007,
		fmt = '4.Dự đoán cần dùng vàng, mỗi lần dự đoán chỉ chọn được 1 ninja để đặt cược'
	},
	[121008] = {
		id = 121008,
		fmt = '#L10##C0xF76B45#【Chuẩn bị trước trận】'
	},
	[121009] = {
		id = 121009,
		fmt = '1.Giai đoạn chuẩn bị thi đấu kéo dài 3 phút, trong thời gian này Dự đoán có thưởng sẽ bị đóng'
	},
	[121010] = {
		id = 121010,
		fmt = '#L10##C0xF76B45#【Đang thi đấu】:'
	},
	[121011] = {
		id = 121011,
		fmt = '1.Mỗi ngày 12:00 và 20:00 bắt đầu thi đấu đúng giờ, toàn bộ quá trình kéo dài 3 phút'
	},
	[121012] = {
		id = 121012,
		fmt = '2.Các chỉ số thể chất của ninja chạy đua khác nhau sẽ khác nhau, tốc độ và xác suất tăng tốc là 2 chỉ số quan trọng hơn cả'
	},
	[121013] = {
		id = 121013,
		fmt = '3.Giải thích các chỉ số:'
	},
	[121014] = {
		id = 121014,
		fmt = 'a.Tốc độ: tốc độ chạy ban đầu của ninja'
	},
	[121015] = {
		id = 121015,
		fmt = 'b.Thể lực: trong lúc thi đấu ninja sẽ liên tục tiêu hao thể lực, khi thể lực không đủ sẽ vào trạng thái suy yếu (trạng thái suy yếu sẽ bị ảnh hưởng giảm tốc độ), khi thể lực hồi đủ thì trạng thái suy yếu sẽ biến mất'
	},
	[121016] = {
		id = 121016,
		fmt = 'c.Xác suất tăng tốc: trong lúc thi đấu, mỗi khoảng thời gian ninja sẽ có một cơ hội tăng tốc, tốc độ theo thời gian thực sẽ tăng tương ứng'
	},
	[121017] = {
		id = 121017,
		fmt = 'd.Thời gian tăng tốc liên tục: thời gian duy trì khi ninja kích hoạt tăng tốc'
	},
	[121018] = {
		id = 121018,
		fmt = '#L10##C0xF76B45#【Công bố kết quả】:'
	},
	[121019] = {
		id = 121019,
		fmt = '1.Cuộc đua sẽ kết thúc khi tất cả ninja đến đích'
	},
	[121020] = {
		id = 121020,
		fmt = '2.Sau khi đua kết thúc, người chơi có thể nhận thưởng dự đoán trong【Lịch sử đua】(huấn luyện viên chưa từng dự đoán sẽ không có thưởng), có thể xem lại toàn bộ quá trình đua'
	},
	[121021] = {
		id = 121021,
		fmt = '3.Thưởng dự đoán gồm 2 phần: điểm dự đoán, thưởng vật phẩm, tích lũy điểm dự đoán nhất định có thể nhận thưởng mốc tương ứng trong【Thưởng điểm】'
	},
	[121022] = {
		id = 121022,
		fmt = '#L10#4.Ví dụ thưởng dự đoán:'
	},
	[122001] = {
		id = 122001,
		fmt = '#C0xF76B45#【Quy tắc cơ bản】'
	},
