	[124202] = {
		id = 124202,
		fmt = '2.Thực hiện ủy thác cần cử ninja phù hợp yêu cầu ủy thác, trừ điểm hành động và tốn một khoảng thời gian, nếu #C0xF76B45#đáp ứng yêu cầu điểm cộng của ủy thác sẽ thu hoạch thêm bất ngờ!'
	},
	[124203] = {
		id = 124203,
