	},
	[124206] = {
		id = 124206,
		fmt = '4.Thực hiện ủy thác cần tự mình cử ninja, sau khi ủy thác hoàn thành phải #C0xF76B45#tự mình nhận thưởng #C0xFFFFFF#đồng thời #C0xF76B45#có thể thực hiện (bao gồm ủy thác đã xong nhưng chưa nhận thưởng) 3 cái#C0xFFFFFF# hãy sắp xếp hợp lý'
	},
	[124207] = {
		id = 124207,
