	[124703] = {
		id = 124703,
		fmt = '3.Khi dùng bí kíp cấp >1 làm vật liệu cường hóa, sau khi cường hóa thành công sẽ hoàn trả xu vàng đã dùng để cường hóa từ bí kíp vật liệu'
	},
	[124704] = {
		id = 124704,
		fmt = '4.Tăng cấp còn có thể mở khóa trạng thái ngẫu nhiên mới và cường hóa ngẫu nhiên trạng thái ngẫu nhiên đã nhận, số lần cường hóa mỗi dòng trạng thái ngẫu nhiên có giới hạn tối đa'
	},
	[124705] = {
		id = 124705,
		fmt = '5.Giải thích cấp trạng thái bí kíp:'
	},
	[124706] = {
		id = 124706,
		fmt = '#C0xFFFFFF#Phẩm chất'
	},
	[124707] = {
		id = 124707,
		fmt = 'Cấp mở khóa trạng thái'
	},
	[124708] = {
		id = 124708,
		fmt = 'Cấp cường hóa trạng thái'
	},
	[124801] = {
		id = 124801,
		fmt = '#L10##C0xF76B45#Mùa hè rực rỡ, dùng đá bào mát lạnh xua tan bực bội trong lòng'
	},
	[124802] = {
		id = 124802,
		fmt = '#L10##C0xF76B45#【Quy tắc sự kiện】:'
	},
	[124803] = {
		id = 124803,
		fmt = '1.Sau khi sự kiện mở, người chơi sẽ làm đá bào cho Pokémon để giải nhiệt'
	},
	[124804] = {
		id = 124804,
		fmt = '2.Pokémon sau khi ra sân sẽ đưa ra hương vị đá bào mình thích, người chơi phải ghi nhớ yêu cầu trước khi thanh tiến độ kết thúc'
	},
	[124805] = {
		id = 124805,
		fmt = '3.Sau khi thanh tiến độ kết thúc, ninja sẽ giấu yêu cầu đã đưa ra, cần người chơi dựa vào trí nhớ chọn yêu cầu mà ninja đã đưa ra'
	},
	[124806] = {
		id = 124806,
		fmt = '4.Sau khi ninja đầu tiên đưa ra yêu cầu, phải bấm【Bắt đầu làm】để mở tủ lạnh, làm đá bào cho ninja'
	},
	[124807] = {
		id = 124807,
		fmt = '5.Sau khi chọn xong, ninja sẽ đánh giá phục vụ dựa trên lựa chọn của người chơi, đánh giá chia 3 mức'
	},
	[124808] = {
		id = 124808,
		fmt = '#C0xF76B45#Phục vụ hoàn hảo: #C0xFFFFFF#không sai và thứ tự đúng'
	},
	[124809] = {
		id = 124809,
		fmt = '#C0xF76B45#Phục vụ tốt: #C0xFFFFFF#không sai nhưng thứ tự sai'
	},
	[124810] = {
		id = 124810,
		fmt = '#C0xF76B45#Phục vụ có khuyết điểm: #C0xFFFFFF#có yêu cầu chọn sai'
	},
	[124811] = {
		id = 124811,
		fmt = '6.Sau khi phục vụ sẽ hiển thị đánh giá phục vụ, #C0xF76B45#nhưng xin chú ý khách tiếp theo sẽ ra sân đưa yêu cầu rất nhanh, đừng bỏ lỡ thời gian ghi nhớ#C0xFFFFFF#'
	},
	[124812] = {
		id = 124812,
		fmt = '7.Theo số lượt phục vụ tăng lên, yêu cầu ninja đưa ra có thể tăng nhiều hơn'
	},
	[124813] = {
		id = 124813,
		fmt = '8.Sau khi đếm ngược tổng kết thúc sẽ ngừng hoạt động, sẽ tính vật phẩm thưởng cuối cùng theo trạng thái phục vụ của người chơi'
	},
	[124901] = {
		id = 124901,
		fmt = '#L10##C0xF76B45#Bóng dáng linh hoạt trên bãi biển, bóng chuyền bãi biển ninja bắt đầu rồi!'
	},
	[124902] = {
		id = 124902,
		fmt = '#L10##C0xF76B45#【Quy tắc sự kiện】:'
	},
	[124903] = {
		id = 124903,
		fmt = '1.Sau khi sự kiện mở, người chơi có thể chơi bóng chuyền trên bãi biển thỏa thích, mỗi ngày không giới hạn số lần'
	},
	[124904] = {
		id = 124904,
		fmt = '2.Sau khi vào game, người chơi phải chọn 1 trong 3 loại trạng thái làm trạng thái nổi bật của ninja sử dụng'
	},
	[124905] = {
		id = 124905,
		fmt = '3.Sau khi chọn sẽ phái ninja tương ứng ra chiến đấu cho bạn!'
	},
	[124906] = {
		id = 124906,
		fmt = '4.Sân mặc định bên trái là sân phe mình, bên phải là sân đối thủ'
	},
	[124907] = {
		id = 124907,
		fmt = '5.Người chơi có thể di chuyển ninja trái phải, ninja sẽ dùng đầu đánh trả bóng do đối thủ đánh sang, người chơi còn có thể dùng 3 cách thao tác bên dưới để thể hiện\n'
	},
	[124908] = {
		id = 124908,
		fmt = '6.Đánh trả bóng vào khu vực đối thủ, đối thủ không đỡ được thì được 1 điểm'
	},
	[124909] = {
		id = 124909,
		fmt = '7.Nếu đánh ra ngoài khu vực đối thủ, hoặc do sai sót của bản thân đánh ra ngoài, sẽ cho đối thủ 1 điểm'
	},
	[124910] = {
		id = 124910,
		fmt = '8.Bên nào được 3 điểm trước sẽ thắng'
	},
	[124911] = {
		id = 124911,
		fmt = '9.Hoàn thành nhiệm vụ tương ứng nhận rất nhiều phần thưởng'
	},
	[125001] = {
		id = 125001,
		fmt = '#L10##C0xF76B45#Chào mừng đến với cuộc phiêu lưu lễ hội mùa hè'
	},
	[125002] = {
		id = 125002,
		fmt = '#C0xF76B45#Truyền thuyết ngôi đền giữa hồ, cư ngụ Pokémon đẹp nhất thế giới……#C0xFFFFFF#'
	},
	[125003] = {
		id = 125003,
		fmt = '#C0xF76B45#Giải thích cơ bản: #C0xFFFFFF#'
	},
	[125004] = {
		id = 125004,
		fmt = '1.Mỗi ngày mở số lượng ải cố định, ải chưa vượt qua có thể thử khiêu chiến lại'
	},
	[125005] = {
		id = 125005,
		fmt = '2.Sau khi ải vượt qua lần đầu sẽ không thể khiêu chiến lại, phải vượt ải trước mới mở khiêu chiến ải tiếp theo'
	},
	[125006] = {
		id = 125006,
		fmt = '3.Đối thoại trong ải ẩn chứa mẹo vượt ải, sau khi vượt qua có thể xem lại cốt truyện ở màn hình thông tin'
	},
	[125007] = {
		id = 125007,
		fmt = '#C0xF76B45#Mẹo vượt ải: #C0xFFFFFF#chú ý nội dung đối thoại cốt truyện'
	},
	[125008] = {
		id = 125008,
		fmt = '#C0xF76B45#Thưởng ải: #C0xFFFFFF#vượt qua nhận thưởng lần đầu'
	},
	[125101] = {
		id = 125101,
		fmt = '#C0x5E565D#*Toàn bộ bonus trạng thái yêu cầu ninja cùng series trong túi ninja đã bồi dưỡng đến 1 sao thì tự động có hiệu lực'
	},
	[125102] = {
		id = 125102,
		fmt = '#C0x5E565D#*Toàn bộ bonus trạng thái chỉ có hiệu lực trong lượt chơi này'
	},
