	[125301] = {
		id = 125301,
		fmt = '1.Trong thời gian sự kiện, hoàn thành nhiệm vụ có thể cầu nguyện trong màn hình sự kiện'
	},
	[125302] = {
		id = 125302,
		fmt = '2.Khi cầu nguyện có thể nhận phúc thường ngẫu nhiên, cũng có thể nhận phúc may mắn'
	},
	[125303] = {
		id = 125303,
		fmt = '3.Mỗi lần cầu nguyện, nếu không nhận phúc may mắn sẽ thắp sáng 1 thẻ may mắn, thẻ may mắn thắp càng nhiều thì cơ hội nhận phúc may mắn càng cao, khi thắp sáng toàn bộ thẻ may mắn trong màn hình, lần sau chắc chắn nhận phúc may mắn'
	},
	[125304] = {
		id = 125304,
		fmt = '4.Nhiệm vụ reset đúng giờ mỗi ngày, hãy chú ý hoàn thành và nhận kịp thời, số lần cầu nguyện đã nhận không reset, sẽ giữ đến khi sự kiện kết thúc'
	},
	[125305] = {
		id = 125305,
		fmt = '5.Nhật ký cầu nguyện ở màn hình nhiệm vụ cầu nguyện, có thể xem nội dung phần thưởng nhận được trong sự kiện lần này'
	},
	[125401] = {
		id = 125401,
		fmt = '1.Giới hạn tối đa mail #C0xF76B45#60#C0xFFFFFF# thư'
	},
	[125402] = {
		id = 125402,
		fmt = '2.Khi vượt giới hạn tối đa mail, một số mail cũ sẽ biến mất, hãy xử lý kịp thời'
	},
	[125501] = {
		id = 125501,
		fmt = '#L10##C0xF76B45#Kẻ mạnh, chào mừng đến với Chiến Đấu Phòng'
	},
	[125502] = {
		id = 125502,
		fmt = '#L10##C0xF76B45#【Quy tắc tuyển chọn】'
	},
	[125503] = {
		id = 125503,
		fmt = '1.Dự án phòng ở nhiều server, tuyển chọn tổng cộng #C0xF76B45#16#C0xFFFFFF# tổ chức mạnh tham chiến'
	},
	[125504] = {
		id = 125504,
		fmt = '2.Dự án sẽ dựa theo điểm tích lũy chiến tranh tổ chức 3 tuần để tuyển chọn (xem trong màn hình Chiến Đấu Phòng), #C0xF76B45#hạng 1 và 2#C0xFFFFFF# của bảng xếp hạng tổ chức sẽ được chọn trực tiếp'
	},
	[125505] = {
		id = 125505,
		fmt = '3.Nếu cụm liên server được ghép cặp không thể gom đủ số tổ chức mà dự án yêu cầu, sẽ chọn theo tổ chức hạng 3~5 về điểm chiến tranh tổ chức trong cùng cụm liên server (ưu tiên chọn tổ chức có tổng lực cao hơn)'
	},
	[125506] = {
		id = 125506,
		fmt = '4.Sau khi chiến tranh tổ chức 3 tuần kết thúc sẽ khóa tổ chức và thành viên tham chiến trong tổ chức, thành viên gia nhập tổ chức được chọn sau đó sẽ không thể tham gia Chiến Đấu Phòng kỳ này'
	},
	[125507] = {
		id = 125507,
		fmt = '#L10##C0xF76B45#【Quy tắc cơ bản】'
	},
	[125508] = {
		id = 125508,
		fmt = '1.Chiến Đấu Phòng lấy #C0xF76B45#4 tuần#C0xFFFFFF# làm 1 mùa, ghi nhận dữ liệu xếp hạng điểm chiến tranh tổ chức 3 tuần, tuần thứ 4 mở'
	},
	[125509] = {
		id = 125509,
		fmt = '2.Chiến Đấu Phòng chia thành 2 giai đoạn vòng loại và vòng chung kết, vòng loại là #C0xF76B45#Thứ Sáu#C0xFFFFFF# của tuần mở, vòng chung kết là #C0xF76B45#Chủ Nhật#C0xFFFFFF# của tuần mở'
	},
	[125510] = {
		id = 125510,
		fmt = '3.Tổ chức được chọn, hệ thống sẽ tự động đăng ký cho thành viên tổ chức, thành viên trong tổ chức phải trong #C0xF76B45#9:00~20:50#C0xFFFFFF# chọn nhóm dự án của mình và đội hình ra trận tương ứng'
	},
	[125511] = {
		id = 125511,
		fmt = '4.Người chơi không chọn chiến trường trước khi thi đấu 10 phút, hệ thống sẽ ngẫu nhiên phân chiến trường và chọn ninja có lực chiến tương đối cao để lập đội'
	},
	[125512] = {
		id = 125512,
		fmt = '5.Thời gian bắt đầu thi đấu chính thức: #C0xF76B45#21:00#C0xFFFFFF#'
	},
	[125513] = {
		id = 125513,
		fmt = '#L10##C0xF76B45#【Quy tắc vòng loại】'
	},
	[125514] = {
		id = 125514,
		fmt = '1.Giai đoạn vòng loại: 16 tổ chức được chọn, chia theo hạng lực chiến thành 4 nhóm đấu giá, thành viên trong tổ chức phải đăng ký nhóm dự án muốn tham gia trong thời gian quy định'
	},
	[125515] = {
		id = 125515,
		fmt = '2.Nhóm dự án có 3 loại'
	},
	[125516] = {
		id = 125516,
		fmt = 'Nhóm xây dựng 6 người: có thể phái 2 đội, mỗi đội 6 ninja'
	},
	[125517] = {
		id = 125517,
		fmt = 'Nhóm thăm dò 4 người: có thể phái 3 đội, mỗi đội 4 ninja'
	},
	[125518] = {
		id = 125518,
		fmt = 'Nhóm thiết kế 1 người: có thể phái 3 đội, mỗi đội 3 ninja'
	},
	[125519] = {
		id = 125519,
		fmt = 'Người chơi tham chiến chỉ được chọn 1 chiến trường để vào chiến đấu, sau khi kết thúc thời gian đăng ký dự án sẽ khóa nhóm dự án và ninja ra trận, sau khi chiến đấu bắt đầu không thể chỉnh sửa'
	},
	[125520] = {
		id = 125520,
		fmt = '3.Trong chiến đấu, sau khi đội 1 bị đánh bại, đội 2 có thể tiếp tục chiến đấu ở hiệp tiếp theo'
	},
	[125521] = {
		id = 125521,
		fmt = '4.Hình thức thi đấu là chế độ hỗn chiến, bạn sẽ ghép cặp với người chơi ngoài tổ chức của mình để chiến đấu trước (khi người chơi còn lại đều là người chơi trong tổ chức mình, chiến đấu kết thúc)'
	},
	[125522] = {
		id = 125522,
		fmt = '5.Người chơi thắng có thể tiếp tục chiến đấu hiệp tiếp theo, chiến đấu với đối thủ ngoài tổ chức mình còn lại'
	},
	[125523] = {
		id = 125523,
		fmt = '6.Người chơi không có ninja ra trận sẽ bị loại tạm thời, nếu người chơi bị loại thuộc tổ chức mà tổ chức đó thăng cấp vòng chung kết thành công thì sẽ cùng thăng cấp, nếu tổ chức đó thăng cấp thất bại thì không có phần tranh đoạt vô địch lần này'
	},
	[125524] = {
		id = 125524,
		fmt = '6.Sau mỗi trận chiến đấu kết thúc sẽ giữ lại HP và chakra'
	},
	[125525] = {
		id = 125525,
		fmt = '7.Chiến Đấu Phòng có cơ chế điểm, nhóm dự án khác nhau thắng thua nhận điểm khác nhau'
	},
	[125526] = {
		id = 125526,
		fmt = 'Nhóm xây dựng 6 người: thắng nhận #C0xF76B45#9#C0xFFFFFF# điểm, thua nhận #C0xF76B45#3#C0xFFFFFF# điểm'
	},
	[125527] = {
		id = 125527,
		fmt = 'Nhóm thăm dò 4 người: thắng nhận #C0xF76B45#8#C0xFFFFFF# điểm, thua nhận #C0xF76B45#2#C0xFFFFFF# điểm'
	},
	[125528] = {
		id = 125528,
		fmt = 'Nhóm thiết kế 1 người: thắng nhận #C0xF76B45#10#C0xFFFFFF# điểm, thua nhận #C0xF76B45#4#C0xFFFFFF# điểm'
	},
	[125529] = {
		id = 125529,
		fmt = '8.Sau chiến đấu, theo số người chơi sống sót của tổ chức sẽ có thưởng điểm cộng thêm'
	},
	[125530] = {
		id = 125530,
		fmt = '9.Tổ chức có thăng cấp hay không dựa vào tổng điểm của thành viên tổ chức ngày đó trong các nhóm dự án khác nhau'
	},
	[125531] = {
		id = 125531,
		fmt = '10.Hai bên chiến đấu tối đa 10 hiệp, hết thời gian nếu vẫn chưa phân thắng bại, bên có %HP còn lại nhiều hơn thắng'
	},
	[125532] = {
		id = 125532,
		fmt = '11.Sau khi vòng loại kết thúc, 4 nhóm chiến đấu sẽ chọn hạng nhất của mình vào vòng chung kết, tổ chức khác bị loại'
	},
	[125533] = {
		id = 125533,
		fmt = '#L10##C0xF76B45#【Quy tắc vòng chung kết】'
	},
	[125534] = {
		id = 125534,
		fmt = '1.Dựa theo thành tích vòng loại, chọn 4 tổ chức mạnh vào tranh đoạt vô địch cuối cùng'
	},
	[125535] = {
		id = 125535,
		fmt = '2.Hệ thống vòng chung kết giống vòng loại'
	},
	[125536] = {
		id = 125536,
		fmt = '3.Cuối cùng dựa theo cơ chế điểm như vòng loại để xếp hạng vòng chung kết, quyết định hạng 1~4'
	},
	[125537] = {
		id = 125537,
		fmt = '4.Tổ chức vô địch sẽ nhận vinh dự tối cao, tất cả tổ chức trong cụm liên server đều nhìn thấy'
	},
	[125538] = {
		id = 125538,
		fmt = '#L10##C0xF76B45#【Thay đổi năng lực ninja】'
	},
	[125539] = {
		id = 125539,
		fmt = '1.Trong suốt Chiến Đấu Phòng, ở mỗi hiệp chiến đấu, toàn bộ ninja lần đầu vào đội chiến đấu sẽ nhận bonus trạng thái Taijutsu, Ninjutsu, Phòng thủ, Kháng, Tốc độ'
	},
	[125540] = {
		id = 125540,
		fmt = '2.Theo chiến đấu liên tục, bonus trạng thái đó sẽ bị suy giảm, ninja sẽ mệt mỏi, năng lực chiến đấu càng yếu đi'
	},
	[125541] = {
		id = 125541,
		fmt = '3.Sau đó mỗi lần tham gia chiến đấu, Taijutsu, Ninjutsu, Phòng thủ, Kháng, Tốc độ, lượng nhận trị liệu của ninja trong đội sẽ tiếp tục giảm'
	},
	[125542] = {
		id = 125542,
		fmt = '#L10##C0xF76B45#【Quy tắc dự đoán】'
	},
	[125543] = {
		id = 125543,
		fmt = '1.Tất cả người chơi trong cùng cụm liên server đều có thể tham gia dự đoán (bao gồm người chơi tham gia chiến đấu)'
	},
	[125544] = {
		id = 125544,
		fmt = '2.Vòng loại và vòng chung kết đều có thể dự đoán'
	},
	[125545] = {
		id = 125545,
		fmt = 'Giai đoạn vòng loại người chơi có thể dự đoán 4 lần (mỗi nhóm chiến đấu 1 lần) mục tiêu dự đoán là tổ chức thăng cấp vào vòng chung kết'
	},
	[125546] = {
		id = 125546,
		fmt = 'Giai đoạn vòng chung kết người chơi có thể dự đoán 1 lần mục tiêu dự đoán là quán quân'
	},
	[125547] = {
		id = 125547,
		fmt = '3.Dự đoán cần dùng xu tổ chức, mỗi lần dự đoán vòng loại cần 500, dự đoán vòng chung kết cần 2000 xu tổ chức'
	},
	[125548] = {
		id = 125548,
		fmt = '4.Tất cả người chơi tham gia dự đoán đều có phần thưởng, phần thưởng phát qua mail'
	},
	[125549] = {
		id = 125549,
		fmt = '#L10##C0xF76B45#【Quy tắc phần thưởng】'
	},
	[125550] = {
		id = 125550,
		fmt = '1.Sau khi thi đấu kết thúc, toàn bộ phần thưởng sẽ gửi qua mail'
	},
	[125551] = {
		id = 125551,
		fmt = '2.Chiến Đấu Phòng là chiến tranh vinh dự của đơn vị tổ chức, phần thưởng hạng tổ chức là toàn bộ nhân sự tham chiến của tổ chức đó đều nhận'
	},
	[125552] = {
		id = 125552,
		fmt = '3.Tổ chức tham gia vòng loại và vòng chung kết đều nhận được 1 bộ phần thưởng'
	},
	[125553] = {
		id = 125553,
		fmt = '4.Tổ chức đoạt quán quân vòng chung kết sẽ nhận được hiển thị vinh dự cao nhất trong cụm liên server'
	},
	[125554] = {
		id = 125554,
		fmt = '5.Phần thưởng hạng điểm xem chi tiết tại hiển thị phần thưởng bên dưới'
	},
	[125601] = {
		id = 125601,
		fmt = '#L10##C0xF76B45#【Dự đoán vòng loại và vòng chung kết】'
	},
	[125602] = {
		id = 125602,
		fmt = '1.Người chơi có thể dự đoán vào ngày thi đấu lớn'
	},
	[125603] = {
		id = 125603,
		fmt = '2.Thời gian dự đoán là Thứ Sáu và Chủ Nhật 9:00~20:50'
	},
	[125604] = {
		id = 125604,
		fmt = '3.Tất cả người chơi trong cùng cụm liên server đều có thể tham gia dự đoán'
	},
	[125605] = {
		id = 125605,
		fmt = '4.Giai đoạn vòng loại, có thể dự đoán 1 tổ chức trong mỗi khu vực, tổng cộng 4 nhóm, mục tiêu dự đoán là hạng nhất của nhóm'
	},
	[125606] = {
		id = 125606,
		fmt = '5.Giai đoạn vòng chung kết, có thể chọn 1 trong 4 tổ chức, mục tiêu dự đoán là tổ chức quán quân'
	},
	[125607] = {
		id = 125607,
		fmt = '6.Mỗi lần dự đoán sẽ tiêu hao một lượng xu tổ chức'
	},
	[125608] = {
		id = 125608,
		fmt = '7.Người chơi dự đoán đúng sẽ nhận thưởng vật phẩm, người chơi dự đoán sai cũng nhận thưởng an ủi'
	},
	[125609] = {
		id = 125609,
		fmt = '8.Nếu người chơi dự đoán đúng cả 5 lần sẽ nhận thêm phần thưởng'
	},
	[125701] = {
		id = 125701,
		fmt = '1.Trò chơi này là game nhập vai có nhiều lối chơi, phù hợp người dùng từ đủ 16 tuổi trở lên, khuyến nghị người chưa thành niên sử dụng sản phẩm game dưới sự giám hộ của phụ huynh'
	},
	[125702] = {
		id = 125702,
		fmt = '2.Trò chơi này thông qua nhập vai cơ bản mô phỏng "ninja", thúc đẩy phát triển cốt truyện qua nhiệm vụ chính tuyến, trong game còn có bồi dưỡng, thu thập trang bị, trải nghiệm ải, trong game có hệ thống xã hội người lạ trao đổi tự do như văn bản, giọng nói, hình ảnh, nhưng việc quản lý hệ thống xã hội tuân thủ pháp luật quy định liên quan'
	},
	[125703] = {
		id = 125703,
		fmt = '3.Trong game này có hệ thống xác thực danh tính người dùng, người dùng xác thực là người chưa thành niên sẽ được quản lý như sau: dưới 8 tuổi không thể nạp, từ 8 tuổi trở lên dưới 16 tuổi số tiền nạp một lần không quá 50 Nhân dân tệ, tổng nạp mỗi tháng không quá 200 Nhân dân tệ, từ 16 tuổi trở lên dưới 18 tuổi số tiền nạp một lần không quá 100 Nhân dân tệ, tổng nạp mỗi tháng không quá 400 Nhân dân tệ, người dùng chưa thành niên chỉ được cung cấp dịch vụ game online 1 giờ mỗi ngày từ 20:00 đến 21:00 vào Thứ Sáu, Thứ Bảy, Chủ Nhật và ngày nghỉ theo quy định pháp luật, thời gian khác không cung cấp dịch vụ game online cho người chưa thành niên dưới bất kỳ hình thức nào'
	},
	[125704] = {
		id = 125704,
		fmt = '4.Thao tác trong cảnh game có lợi cho việc rèn luyện phối hợp tay mắt, năng lực cảm nhận không gian và phản xạ nhanh của người chơi, ải tổ đội trong game giúp tăng năng lực giao tiếp, năng lực hợp tác, tầm nhìn tổng thể của người chơi, bồi dưỡng tuyến trong game giúp tăng năng lực quản lý tài nguyên, năng lực thống kê toán học của người chơi'
	},
	[125705] = {
		id = 125705,
		fmt = 'Học viên Trường Ninja mỗi ngày nhận: Phiếu giới hạn thời gian*128 Mảnh đa dụng SS*5 Xu vàng*20k'
