	},
	[125713] = {
		id = 125713,
		fmt = 'Ninja Truyền Thuyết mỗi ngày nhận: Phiếu giới hạn thời gian*1200 Mảnh đa dụng SSS*30 Xu vàng*72k'
	},
	[125714] = {
		id = 125714,
		fmt = 'Bán cấp Lục Đạo mỗi ngày nhận: Phiếu giới hạn thời gian*1300 Mảnh đa dụng SSS*30 Xu vàng*80k'
	},
	[125715] = {
		id = 125715,
		fmt = 'Sức Mạnh Lục Đạo mỗi ngày nhận: Phiếu giới hạn thời gian*1400 Mảnh đa dụng SSS*40 Xu vàng*90k'
	},
	[125716] = {
		id = 125716,
		fmt = 'Mạnh Nhất Thế Giới Ninja mỗi ngày nhận: Phiếu giới hạn thời gian*1500 Mảnh đa dụng SSS*40 Xu vàng*99k'
	},
	[125801] = {
		id = 125801,
		fmt = '1.Gắn ảo thuật nhận được vào ảo thuật, kích hoạt ảo thuật để nhận trạng thái cực mạnh!'
	},
	[125802] = {
		id = 125802,
		fmt = '2.Trong Vùng Đất Bí Ẩn có nhiều bản khắc, mỗi bản khắc gắn không ít ảo thuật, các ảo thuật này có trạng thái bí ẩn, cần dùng vật phẩm ảo thuật thu thập được để gắn, khi tất cả ảo thuật trên 1 ảo thuật được gắn xong sẽ nhận bonus trạng thái'
	},
	[125803] = {
		id = 125803,
		fmt = '3.Mỗi ảo thuật chỉ có thể kích hoạt 1 lần, sau khi kích hoạt nhận trạng thái ngay, trong đó còn có một số ảo thuật kèm bonus trạng thái riêng cho một số loại ninja hệ nhất định, có thể bấm xem ảo thuật'
	},
	[125804] = {
		id = 125804,
		fmt = '4.Mỗi bản khắc ghi lại chỉ số trạng thái do kích hoạt ảo thuật có thể cho Sổ Tay Nhà Phiêu Lưu xem, đồng thời cũng nhận được thưởng kích hoạt, xem trong Tổng Quan Thu Thập'
	},
	[125805] = {
		id = 125805,
		fmt = '5.Kích hoạt ảo thuật ngoài nhận bonus trạng thái còn tích lũy năng lượng ảo thuật, năng lượng ảo thuật tích lũy không chỉ cho bạn bonus trạng thái tăng thêm mà còn mở khóa bản khắc bí ẩn mới khác!'
	},
	[125901] = {
		id = 125901,
		fmt = '1.Chào mừng đến Trung Tâm, đây là "lõi" của Nhà, phụ trách xử lý các vấn đề quản lý khác nhau của cư dân và ninja'
	},
	[125902] = {
		id = 125902,
		fmt = '2.Trung Tâm có thể #C0xF76B45#nâng cấp#C0x5B545B#, chỉ cần chuẩn bị đủ một số vật phẩm nguyên liệu, kiến trúc tốt cần chạm khắc tỉ mỉ nên có thể phải chờ một thời gian, nếu không muốn chờ cũng có thể dùng một ít vàng để hoàn thành nhanh'
	},
	[125903] = {
		id = 125903,
		fmt = '3.#C0xF76B45#Nâng cấp hoặc mở khóa kiến trúc khác trong Nhà sẽ liên quan đến cấp Trung Tâm#C0x5B545B#, phải đạt cấp Trung Tâm để mở khóa kiến trúc sẽ thông báo trong màn hình nâng cấp của màn hình Trung Tâm, phải đạt cấp Trung Tâm để mở rộng giới hạn tối đa của kiến trúc khác sẽ hiển thị điều kiện trong màn hình nâng cấp của từng kiến trúc tương ứng'
	},
	[126001] = {
		id = 126001,
		fmt = '1.Chào mừng đến các Xưởng Chế Tạo, các kiến trúc này phụ trách cung cấp tiện ích xây dựng và sinh hoạt cho cư dân và ninja của Nhà'
	},
	[126002] = {
		id = 126002,
		fmt = '#C0xF76B45#【Về các Xưởng Chế Tạo】'
	},
	[126003] = {
		id = 126003,
		fmt = '1.Tại #C0xF76B45#Mỏ Khoáng, Trạm Tráng Miệng, Bãi Đốn Gỗ#C0x5B545B# sẽ #C0xF76B45#liên tục sản xuất vật phẩm#C0x5B545B#, vật phẩm chủ yếu dùng để xây dựng và Phiêu Lưu Ninja, còn #C0xF76B45#Ngân Hàng Tài Chính#C0x5B545B# cần #C0xF76B45#tự đặt lệnh#C0x5B545B# mới bắt đầu sản xuất, chủ yếu sản xuất tiền tệ'
	},
	[126004] = {
		id = 126004,
		fmt = '2.Xưởng sản xuất vật phẩm liên tục #C0xF76B45#mỗi khoảng thời gian có thể nhận vật phẩm sản xuất#C0x5B545B#, khi chưa nhận sẽ chiếm chỗ kho xưởng, #C0xF76B45#khi kho đầy xưởng sẽ ngừng làm việc#C0x5B545B#, còn Ngân Hàng Tài Chính có #C0xF76B45#giới hạn số lệnh#C0x5B545B#, mỗi lần sản xuất #C0xF76B45#không thể đặt vượt giới hạn tối đa#C0x5B545B#, sau khi sản xuất xong nhận tiền tệ một lần'
	},
	[126005] = {
		id = 126005,
		fmt = '3.Tất cả kiến trúc cũng có thể #C0xF76B45#nâng cấp#C0x5B545B#, điều kiện nâng cấp không giống nhau, sau khi nâng cấp #C0xF76B45#giới hạn tối đa kho, hiệu suất sản xuất và tiêu hao năng lượng ninja#C0x5B545B# của mỗi xưởng sẽ thay đổi'
	},
	[126006] = {
		id = 126006,
		fmt = '4.Trong Xưởng Chế Tạo có thể #C0xF76B45#đặt trước đội trực#C0x5B545B#, giúp huấn luyện viên tiện #C0xF76B45#phân bổ ninja trực tiếp từ đội đã đặt trước#C0x5B545B# vào Xưởng Chế Tạo trực! Lưu ý chức năng cần huấn luyện viên đạt #C0xF76B45#một cấp nhất định#C0x5B545B# mới mở, sau khi mở #C0xF76B45#phải mở khóa đủ 3 ô trực trong xưởng này#C0x5B545B# mới dùng được~'
	},
	[126007] = {
		id = 126007,
		fmt = '#C0xF76B45#【Ninja trực】'
	},
	[126008] = {
		id = 126008,
		fmt = '1.Tất cả kiến trúc đều có thể cử ninja vào đó trực, #C0xF76B45#mỗi kiến trúc hỗ trợ tối đa 3 ninja#C0x5B545B#, trực cần tiêu hao năng lượng ninja, ninja không có năng lượng sẽ ngừng trực và phải #C0xF76B45#tự rút#C0x5B545B#, tiêu hao năng lượng trừ theo tiêu chuẩn của xưởng hiện tại'
	},
	[126009] = {
		id = 126009,
		fmt = '2.Trong toàn bộ Xưởng Chế Tạo, mỗi lần phân bổ 1 ninja trực và ở #C0xF76B45#trạng thái làm việc#C0x5B545B# sẽ nhận #C0xF76B45#hiệu ứng bonus cho giới hạn tối đa kho, hiệu suất sản xuất, giảm tiêu hao lệnh chợ#C0x5B545B#, hiệu ứng bonus thường hiển thị ở màn hình xưởng tương ứng, có thể xem'
	},
	[126010] = {
		id = 126010,
		fmt = '3.Khi Xưởng Chế Tạo ngừng làm việc (xưởng sản xuất liên tục kho đầy, Ngân Hàng Tài Chính hiện tại chưa nhận lệnh) ninja cũng sẽ ngừng làm việc, lúc này #C0xF76B45#sẽ không trừ năng lượng ninja nữa#C0x5B545B# cho đến khi họ bắt đầu trực lại'
	},
	[126011] = {
		id = 126011,
		fmt = '4.Khi bố trí ninja làm việc trực, ninja sẽ ở #C0xF76B45#trạng thái làm việc#C0x5B545B#, không thể dùng ở nơi khác trong Nhà, có thể rút ninja bất cứ lúc nào, khi rút sẽ trừ theo năng lượng đã tiêu hao hiện tại'
	},
	[126012] = {
		id = 126012,
